window.LECTURE = {"p1": [{"n": 1, "title": "Inference & Knowledge Representation", "dur": 45480, "clicks": [], "segs": [{"click": 0, "sents": [[0, "Welcome."], [1010, "Today is a long session, and a very important one."], [5240, "Over the last few weeks we learned how to write knowledge down in first-order logic."], [10540, "Today we answer two questions that follow naturally."], [14320, "First: once knowledge is written in logic, how does a computer actually reason with it?"], [20520, "That is Chapter 9, Inference in First-Order Logic."], [24710, "Second: what knowledge should we write down, and how should we organize it so that reasoning works in the real world?"], [31830, "That is Chapter 10, Knowledge Representation."], [35450, "We will go step by step."], [37690, "Every new idea will be built on the screen one piece at a time, so you never have to hold more than one new thing in your head at once."]]}]}, {"n": 2, "title": "Today's Roadmap", "dur": 62080, "clicks": [2175, 22705, 25750, 42815], "segs": [{"click": 0, "sents": [[280, "Here is the plan for today."]]}, {"click": 1, "sents": [[2650, "Part one is Chapter 9, Inference in First-Order Logic."], [7420, "It takes about eighty minutes and has five sections: propositionalization, unification, forward chaining, backward chaining, and resolution."], [18000, "Do not worry about the names yet."], [20120, "Each one will be explained from the beginning."]]}, {"click": 2, "sents": [[23230, "Then we take a ten-minute break."]]}, {"click": 3, "sents": [[26280, "Part two is Chapter 10, Knowledge Representation, about eighty-five minutes."], [32100, "It covers six sections, from ontologies, to events and time, to how an agent reasons about what other agents know, to reasoning with defaults and exceptions."]]}, {"click": 4, "sents": [[43130, "After every section we will do two things."], [46400, "First, we apply the idea to a realistic case: the Northgate Hospital knowledge base and our patient, Maria Santos."], [55120, "Second, we pause for a short, ungraded question so you can check your understanding before we move on."]]}]}, {"n": 3, "title": "Two Running Examples", "dur": 71970, "clicks": [4595, 36970], "segs": [{"click": 0, "sents": [[510, "Throughout Part one we will use two running examples."]]}, {"click": 1, "sents": [[5090, "The first comes straight from the textbook, and we call it the Crime knowledge base."], [10420, "Read the story with me."], [12310, "The law says it is a crime for an American to sell weapons to hostile nations."], [17910, "The country Nono, an enemy of America, has some missiles, and all of its missiles were sold to it by Colonel West, who is American."], [27030, "The question is: is Colonel West a criminal?"], [30970, "Every algorithm in Chapter 9 will answer this same question, so you can compare them fairly."]]}, {"click": 2, "sents": [[37195, "The second example is from the real world."], [40615, "Northgate Hospital runs a clinical decision-support system that watches every patient."], [47145, "Our patient, Maria Santos, has a fever and a high heart rate."], [52415, "Her doctor has prescribed amoxicillin, and her chart records a penicillin allergy."], [58395, "The system must answer: is Maria at risk of sepsis, and should it raise a medication alert?"], [65475, "By the end of Part one, you will be able to trace exactly how a computer reaches those conclusions."]]}]}, {"n": 4, "title": "Chapter 9 in One Picture", "dur": 82190, "clicks": [23325, 39760, 53645, 62450, 71800], "segs": [{"click": 0, "sents": [[525, "Here is the whole chapter in one picture."], [3625, "On the left we have a knowledge base, a collection of facts and rules written in first-order logic, and a question: is some sentence alpha true?"], [13465, "We write K B entails alpha."], [16725, "An inference algorithm is the machinery that connects the two."], [20675, "Chapter 9 gives us five ideas."]]}, {"click": 1, "sents": [[23695, "Section 9.1, propositionalization: turn first-order logic back into simple propositional logic, then reuse the algorithms we already learned in Chapter 7."], [35895, "It works, but we will see that it can explode in size."]]}, {"click": 2, "sents": [[40105, "Section 9.2, unification and Generalized Modus Ponens: a way to match rules to facts directly, without exploding anything."], [50665, "This is the key trick of the whole chapter."]]}, {"click": 3, "sents": [[54005, "Section 9.3, forward chaining: start from the facts and keep firing rules until the goal appears."]]}, {"click": 4, "sents": [[62985, "Section 9.4, backward chaining: start from the goal and work backward to the facts."], [69845, "This is how Prolog works."]]}, {"click": 5, "sents": [[72155, "Section 9.5, resolution: proof by contradiction."], [77465, "It is the most general method, and it works for all of first-order logic."]]}]}, {"n": 5, "title": "Propositionalization", "dur": 34490, "clicks": [14165, 18270, 26795], "segs": [{"click": 0, "sents": [[435, "Section 9.1."], [2465, "The idea here is simple: if we already know how to reason in propositional logic, maybe we can convert first-order logic into propositional logic and reuse what we know."]]}, {"click": 1, "sents": [[14500, "First, we make precise what inference means."]]}, {"click": 2, "sents": [[18780, "Second, we learn two rules for removing quantifiers: Universal Instantiation and Existential Instantiation."]]}, {"click": 3, "sents": [[27130, "Third, we see why this approach, although correct, breaks down when the knowledge base gets large."]]}]}, {"n": 6, "title": "What Is Inference?", "dur": 79360, "clicks": [17580, 40195, 55340], "segs": [{"click": 0, "sents": [[610, "What do we mean by inference?"], [3270, "Inference means deriving new sentences that must be true, given the sentences already in the knowledge base."], [10910, "Nothing is guessed."], [12880, "If the knowledge base is true, the conclusion is guaranteed true."]]}, {"click": 1, "sents": [[18090, "We write it like this: K B, a double-bar turnstile, alpha."], [23660, "Read it as: the knowledge base entails alpha."], [27560, "It means: in every possible world where everything in the knowledge base is true, alpha is also true."], [34980, "Every algorithm today tries to answer exactly this yes-or-no question."]]}, {"click": 2, "sents": [[40570, "Here is an analogy."], [42410, "A knowledge base that cannot reason is like a library full of books, but with no librarian."], [48760, "The information is in there, but nobody can answer your question."], [53090, "Inference is the librarian."]]}, {"click": 3, "sents": [[55790, "A small example."], [57320, "The knowledge base says John is a king, John is greedy, and for all x, if x is a king and x is greedy, then x is evil."], [67820, "We ask: is John evil?"], [70350, "Yes."], [71120, "That sentence is entailed."], [73280, "Our job in this chapter is to show, mechanically, how a computer reaches that yes."]]}]}, {"n": 7, "title": "Universal Instantiation (UI): The Rule", "dur": 75020, "clicks": [12240, 27500, 47785, 64000], "segs": [{"click": 0, "sents": [[320, "Our first inference rule is called Universal Instantiation, or U I."], [6300, "Here is the rule written formally."], [8660, "Do not panic."], [9760, "We will read it one piece at a time."]]}, {"click": 1, "sents": [[12615, "The left side, for all v, alpha, is a sentence that says something about every object."], [19865, "For example: for all x, if x is a king and x is greedy, then x is evil."]]}, {"click": 2, "sents": [[28105, "The right side, S U B S T of v slash g and alpha, means: take the sentence alpha and replace every v with g."], [39105, "The notation in curly braces, x slash John, is called a substitution."], [44935, "Read it as: x becomes John."]]}, {"click": 3, "sents": [[48125, "What is g?"], [49655, "It must be a ground term, which simply means a term with no variables."], [55015, "John is a ground term."], [57025, "Richard is a ground term."], [59015, "Even Father of John is a ground term, because it contains no variables."]]}, {"click": 4, "sents": [[64285, "In plain English: if something is true of everything, then it is true of any particular thing you name."], [71875, "That is all Universal Instantiation says."]]}]}, {"n": 8, "title": "UI Step by Step: The Evil Kings", "dur": 83470, "clicks": [14555, 30815, 45575, 59095, 70825], "segs": [{"click": 0, "sents": [[265, "Let us watch Universal Instantiation work."], [3545, "Our domain has two objects, John and Richard."], [7255, "Our rule says: for all x, if x is a king and x is greedy, then x is evil."]]}, {"click": 1, "sents": [[14855, "Step one."], [16015, "Substitute x becomes John."], [18865, "Every x in the rule turns into John."], [21995, "We get: if John is a king and John is greedy, then John is evil."], [27935, "Notice there are no variables left."]]}, {"click": 2, "sents": [[31275, "Step two."], [32555, "Substitute x becomes Richard."], [35315, "We get: if Richard is a king and Richard is greedy, then Richard is evil."], [41655, "One rule has become two sentences, one per object."]]}, {"click": 3, "sents": [[45795, "Step three."], [47105, "Look at the facts we already know: John is a king, and John is greedy."], [52675, "Now look at the John instance, circled."], [55565, "Its two conditions match our two facts exactly."]]}, {"click": 4, "sents": [[59400, "Step four."], [60630, "Ordinary Modus Ponens from Chapter 7 now applies: if the conditions are true, the conclusion is true."], [67760, "So we conclude: John is evil."]]}, {"click": 5, "sents": [[71290, "Each substitution produced what we call a ground instance, a sentence with no variables left."], [78100, "Once everything is ground, first-order logic looks just like propositional logic."]]}]}, {"n": 9, "title": "Existential Instantiation (EI) and Skolem Constants", "dur": 86310, "clicks": [16020, 28980, 43130, 53350, 70275], "segs": [{"click": 0, "sents": [[350, "The second rule handles the other quantifier, there exists."], [4800, "It is called Existential Instantiation."], [8170, "If we know that some object with a property exists, we give that object a brand-new name, called a Skolem constant."]]}, {"click": 1, "sents": [[16330, "Example."], [17550, "There exists an x such that x is a crown and x is on John's head."], [23420, "In English: there is some crown on John's head."], [27080, "We do not know which crown."]]}, {"click": 2, "sents": [[29350, "So we invent a name for it: C one."], [32760, "Now we write: C one is a crown, and C one is on John's head."], [38550, "C one simply means: that crown, whichever one it is."]]}, {"click": 3, "sents": [[43390, "Rule one: the name must be brand new."], [47020, "If we reused a name like John, we would be claiming that John is the crown, which we do not know."]]}, {"click": 4, "sents": [[53660, "Rule two: use it once."], [56630, "We apply Existential Instantiation one time and then discard the original sentence."], [63120, "Universal Instantiation is different; we can apply it as many times as we like, once per object."]]}, {"click": 5, "sents": [[70560, "Why is this safe?"], [72260, "The new knowledge base is not logically identical to the old one, but it is satisfiable exactly when the old one is."], [80500, "We have only given a name to something that already exists."], [84350, "That is enough for inference."]]}]}, {"n": 10, "title": "When ∃ Sits Inside ∀: Skolem Functions", "dur": 71870, "clicks": [12345, 26430, 44305, 58055], "segs": [{"click": 0, "sents": [[330, "Sometimes the there-exists sits inside a for-all."], [4560, "For all x, there exists y, such that x loves y."], [9530, "In English: everyone loves someone."]]}, {"click": 1, "sents": [[12680, "Can we just name that someone with a constant, K?"], [16340, "No."], [17250, "That would say everyone loves the same person K."], [20760, "That is much stronger than what we know."], [23240, "Ana might love one person and Ben another."]]}, {"click": 2, "sents": [[26890, "Instead we use a Skolem function, F of x."], [31020, "We write: for all x, x loves F of x."], [35660, "Read F of x as: the person that x loves."], [39650, "Because it is a function of x, it can give a different answer for each x."]]}, {"click": 3, "sents": [[44600, "Picture it like this."], [46130, "F of Ana is whoever Ana loves."], [49250, "F of Ben is whoever Ben loves."], [52060, "F of Chen is whoever Chen loves."], [54930, "The function lets the answer depend on the person."]]}, {"click": 4, "sents": [[58390, "So, a Skolem function names the thing that exists and lets it depend on the outer for-all variable."], [65430, "We will meet Skolem functions again in Section 9.5, when we convert sentences for resolution."]]}]}, {"n": 11, "title": "Propositionalization: The Full Procedure", "dur": 66430, "clicks": [8005, 19340, 28405, 42060, 52715], "segs": [{"click": 0, "sents": [[460, "Now we can put the two rules together into a complete procedure called propositionalization."], [6530, "It has four steps."]]}, {"click": 1, "sents": [[8250, "Step one: apply Universal Instantiation to every for-all rule, once for every ground term in the domain."], [16730, "That gives us many ground instances."]]}, {"click": 2, "sents": [[19680, "Step two: apply Existential Instantiation to every there-exists sentence, introducing Skolem constants."]]}, {"click": 3, "sents": [[28935, "Step three: rename."], [31255, "Each ground atom, such as King of John, becomes a single propositional symbol, such as King-John written as one word."], [40125, "The parentheses disappear."]]}, {"click": 4, "sents": [[42415, "Step four: run any propositional algorithm from Chapter 7: truth tables, D P L L, forward chaining, or backward chaining."]]}, {"click": 5, "sents": [[53255, "The result: first-order inference has been reduced to propositional inference, something we already know how to do."], [61285, "So is the problem solved?"], [63515, "Not quite."], [64735, "Let us see what goes wrong."]]}]}, {"n": 12, "title": "Problem 1: Function Symbols Create Infinitely Many Terms", "dur": 65980, "clicks": [13090, 15345, 19105, 24295, 26770, 35075, 56635], "segs": [{"click": 0, "sents": [[305, "Problem one."], [1735, "Suppose our knowledge base contains a function symbol, such as Father."], [6675, "Universal Instantiation says we must try every ground term."], [11405, "Watch how many there are."]]}, {"click": 1, "sents": [[13635, "We start with John."]]}, {"click": 2, "sents": [[15855, "But Father of John is also a ground term."]]}, {"click": 3, "sents": [[19915, "So is Father of Father of John, John's grandfather."]]}, {"click": 4, "sents": [[24715, "And his great-grandfather."]]}, {"click": 5, "sents": [[27250, "And so on, forever."], [29380, "The propositionalized knowledge base becomes infinite."], [32720, "We can never finish writing it down."]]}, {"click": 6, "sents": [[35390, "There is good news from 1930."], [38180, "Herbrand's theorem says: if the sentence is entailed, then a proof exists using only a finite number of ground instances."], [47330, "So we can search in layers: first try terms of depth zero, then depth one, then depth two, until a proof appears."]]}, {"click": 7, "sents": [[57120, "So if alpha is entailed, we will eventually find the proof."], [61810, "But what if alpha is not entailed?"], [64440, "That is problem two."]]}]}, {"n": 13, "title": "Problems 2 and 3: Endless Search and Explosion", "dur": 70120, "clicks": [1850, 27220, 44320, 50790, 57050], "segs": [{"click": 0, "sents": [[290, "Two more problems."]]}, {"click": 1, "sents": [[2310, "Problem two: first-order logic is only semidecidable."], [7040, "If alpha is entailed, our search will eventually say yes."], [11500, "But if alpha is not entailed, the search may run forever, trying deeper and deeper terms, never sure it can stop."], [19590, "No algorithm can always say no."], [22490, "This is closely related to Turing's halting problem from 1936."]]}, {"click": 2, "sents": [[27560, "Problem three: explosion."], [30110, "Even with no function symbols, the number of ground instances grows like p times n to the power k, where p is the number of predicates, n the number of constants, and k the number of arguments per predicate."]]}, {"click": 3, "sents": [[44610, "Let us put numbers in."], [46630, "Say there are fifty predicates, each with three arguments."]]}, {"click": 4, "sents": [[51230, "And there are one hundred constants."], [53740, "One hundred to the power three is one million."]]}, {"click": 5, "sents": [[57545, "Fifty times one million is fifty million ground atoms, from a fairly small knowledge base."], [64635, "Most of them are useless for the question we asked."], [67735, "We need a smarter approach."]]}]}, {"n": 14, "title": "Northgate Hospital: Grounding a Clinical Rule", "dur": 81660, "clicks": [23150, 36575, 43195, 54250, 70430], "segs": [{"click": 0, "sents": [[495, "Now let us apply this to Northgate Hospital."], [3835, "Rule R one says: for every patient p, if p has a fever and p has a high heart rate, then p is at risk of sepsis."], [14105, "Sepsis is a dangerous reaction to infection, so the hospital wants this flagged early."], [20115, "The small gray line defines each predicate."]]}, {"click": 1, "sents": [[23455, "Propositionalization applies Universal Instantiation for every patient."], [29115, "With Maria, we get: if Maria has a fever and a high heart rate, then Maria is at sepsis risk."]]}, {"click": 2, "sents": [[36865, "With James, we get the same sentence about James, even though James is perfectly healthy."]]}, {"click": 3, "sents": [[43755, "Maria's chart says she has a fever and a high heart rate."], [47635, "So Modus Ponens gives: Maria is at sepsis risk."], [51895, "The system should alert her care team."]]}, {"click": 4, "sents": [[54565, "Now scale up."], [56005, "Northgate has four hundred patients and three hundred rules, involving every drug, every lab result, every hour."], [63925, "Grounding everything produces millions of sentences, and almost all of them are about patients who are fine."]]}, {"click": 5, "sents": [[71185, "Notice we only needed one instance, Maria's."], [75175, "What if the computer could jump straight to it?"], [77975, "That is exactly what Section 9.2 shows us."]]}]}, {"n": 15, "title": "Check Your Understanding", "dur": 38240, "clicks": [14085], "segs": [{"click": 0, "sents": [[325, "Check your understanding."], [2195, "Which substitution is a valid use of Universal Instantiation on: for all x, x likes ice cream?"], [10245, "Look at the four options and pick one before I reveal the answer."]]}, {"click": 1, "sents": [[14420, "The answer is B."], [16210, "Father of Ana contains no variables, so it is a ground term, and U I lets us substitute any ground term."], [24100, "Option A still has a variable, y."], [27150, "Option C describes Existential Instantiation, where we invent a new constant and discard the sentence."], [34040, "Option D is not an instance at all; it is a weaker statement."]]}]}, {"n": 16, "title": "Unification", "dur": 36100, "clicks": [12160, 19250, 27015], "segs": [{"click": 0, "sents": [[310, "Section 9.2, unification."], [3880, "This is the most important idea in the chapter."], [7350, "Forward chaining, backward chaining, and resolution all depend on it."]]}, {"click": 1, "sents": [[12610, "First, the idea: find the substitution that makes two sentences look exactly the same."]]}, {"click": 2, "sents": [[20110, "Second, we work four examples by hand, one argument at a time, so you can do this yourself."]]}, {"click": 3, "sents": [[27390, "Third, we combine unification with Modus Ponens to get Generalized Modus Ponens, the workhorse rule of inference."]]}]}, {"n": 17, "title": "The Idea: Ask for Only the Substitution You Need", "dur": 61550, "clicks": [4120, 18045, 31440, 37185, 45955], "segs": [{"click": 0, "sents": [[340, "Before the formal definition, let us get the idea."]]}, {"click": 1, "sents": [[4600, "Propositionalization, from Section 9.1, generates every instance of a rule and then looks for one that matches a fact."], [13720, "It is like printing every key in the city just to open one door."]]}, {"click": 2, "sents": [[18280, "Unification works differently."], [20780, "It looks at the rule and the fact side by side and computes the one substitution that makes them match."], [28120, "It is like cutting a single key to fit the lock."]]}, {"click": 3, "sents": [[31645, "For example, can King of x and King of John be made identical?"]]}, {"click": 4, "sents": [[37475, "Yes."], [38355, "If x becomes John, both sentences read King of John."], [43235, "That substitution is called theta."]]}, {"click": 5, "sents": [[46475, "Why does this matter?"], [48225, "Only the substitutions needed for this particular inference are ever computed."], [53495, "There is no explosion."], [55575, "This one idea is what makes Prolog, theorem provers, and rule engines practical."]]}]}, {"n": 18, "title": "UNIFY(p, q): The Definition", "dur": 74170, "clicks": [25890, 36040, 50110, 58400], "segs": [{"click": 0, "sents": [[505, "Here is the formal definition."], [2775, "UNIFY takes two sentences, p and q, and returns a substitution theta such that applying theta to p gives exactly the same result as applying theta to q."], [15215, "If no such substitution exists, UNIFY returns failure."], [19785, "To compute it, we compare the sentences position by position using four simple rules."]]}, {"click": 1, "sents": [[26215, "Rule one: a variable meets anything."], [29575, "Bind the variable to it."], [31635, "If x meets John, record x slash John."]]}, {"click": 2, "sents": [[36615, "Rule two: two constants meet."], [39585, "If they have the same name, fine, move on."], [42765, "If the names differ, like John and Bill, unification fails."], [47875, "Constants never change."]]}, {"click": 3, "sents": [[50385, "Rule three: if a variable has already been bound earlier, replace it with its value first, and then compare."]]}, {"click": 4, "sents": [[58895, "Rule four: two compound terms, like Mother of y and Mother of John."], [65525, "If the function names match, unify their arguments one by one."], [70515, "Those four rules are everything."], [72905, "Let us practice."]]}]}, {"n": 19, "title": "Example 1:  UNIFY(King(x), King(John))", "dur": 45840, "clicks": [9590, 17635, 34915], "segs": [{"click": 0, "sents": [[385, "Example one."], [1765, "Unify King of x with King of John."], [4805, "We line them up: predicate in the first column, then each argument."]]}, {"click": 1, "sents": [[9895, "Step one: compare the predicate names."], [13375, "King and King."], [15215, "Same name, so we keep going."]]}, {"click": 2, "sents": [[18155, "Step two: compare argument one."], [21335, "On top we have x, a variable."], [24105, "Below we have John, a constant."], [26955, "Rule one says a variable meets anything, so we bind x to John and write x slash John into theta."]]}, {"click": 3, "sents": [[35635, "No more columns."], [37145, "Theta is x slash John."], [39635, "Apply it to both sentences and both become King of John."], [43935, "Unification succeeded."]]}]}, {"n": 20, "title": "Example 2:  UNIFY(Knows(John, x), Knows(y, Bill))", "dur": 48680, "clicks": [10585, 16465, 28055, 36290], "segs": [{"click": 0, "sents": [[325, "Example two."], [1775, "Knows of John comma x, and Knows of y comma Bill."], [7395, "Notice the variables are on different sides this time."]]}, {"click": 1, "sents": [[10925, "Predicates first: Knows and Knows."], [14565, "Same, keep going."]]}, {"click": 2, "sents": [[16985, "Argument one: John on top, y below."], [21465, "y is a variable, so bind y to John."], [25085, "It does not matter which side the variable is on."]]}, {"click": 3, "sents": [[28385, "Argument two: x on top, Bill below."], [32795, "x is a variable, so bind x to Bill."]]}, {"click": 4, "sents": [[36820, "Theta is y slash John and x slash Bill."], [41000, "Apply it and both sentences read: Knows of John comma Bill."], [46090, "In English: John knows Bill."]]}]}, {"n": 21, "title": "Example 3:  UNIFY(Knows(John, x), Knows(y, Mother(y)))", "dur": 48870, "clicks": [8820, 12990, 18725, 37145], "segs": [{"click": 0, "sents": [[360, "Example three adds a function."], [3080, "Knows of John comma x, and Knows of y comma Mother of y."]]}, {"click": 1, "sents": [[9140, "Predicates: Knows and Knows."], [12200, "Same."]]}, {"click": 2, "sents": [[13290, "Argument one: John against y."], [16680, "Bind y to John."]]}, {"click": 3, "sents": [[19290, "Argument two: x against Mother of y."], [22970, "But wait, y already has a value, John."], [26260, "Rule three says replace it first."], [29050, "So Mother of y becomes Mother of John."], [32620, "Now x is a variable, so bind x to Mother of John."]]}, {"click": 4, "sents": [[37490, "Theta is y slash John and x slash Mother of John."], [42150, "Both sentences become: Knows of John comma Mother of John."], [47130, "John knows his mother."]]}]}, {"n": 22, "title": "Example 4:  UNIFY(Knows(John, x), Knows(x, Elizabeth))", "dur": 46230, "clicks": [10590, 12965, 18705, 32745], "segs": [{"click": 0, "sents": [[450, "Example four looks almost the same, but watch carefully."], [4870, "Knows of John comma x, and Knows of x comma Elizabeth."]]}, {"click": 1, "sents": [[10930, "Predicates: same."]]}, {"click": 2, "sents": [[13480, "Argument one: John against x."], [16930, "Bind x to John."]]}, {"click": 3, "sents": [[19020, "Argument two: x against Elizabeth."], [22790, "But x is already John."], [25040, "So we are really comparing John with Elizabeth: two different constants."], [30450, "Rule two says that fails."]]}, {"click": 4, "sents": [[33090, "Unification fails."], [35210, "x cannot be John and Elizabeth at the same time."], [39060, "But is that the right answer?"], [41230, "Think about what these sentences mean."], [43640, "Let us look more closely on the next slide."]]}]}, {"n": 23, "title": "Fixing Example 4: Standardizing Apart", "dur": 62060, "clicks": [19825, 32090, 45445], "segs": [{"click": 0, "sents": [[440, "Read the two sentences in English."], [3190, "Remember, variables are implicitly for all."], [7130, "Sentence one, Knows of John comma x, says John knows everyone."], [13480, "Sentence two, Knows of x comma Elizabeth, says everyone knows Elizabeth."]]}, {"click": 1, "sents": [[20240, "The two x's are unrelated."], [22680, "They just happen to share a name, like two students in the same class both called Alex."], [28220, "Treating them as the same variable caused the false failure."]]}, {"click": 2, "sents": [[32430, "So before unifying, we rename the variables in one sentence so that no names are shared."], [39020, "This is called standardizing apart."], [41930, "Here, the second x becomes x seventeen."]]}, {"click": 3, "sents": [[45750, "Now unification succeeds: x seventeen becomes John and x becomes Elizabeth."], [52600, "The conclusion is: John knows Elizabeth, which is exactly right."], [57620, "Every real inference engine standardizes apart automatically."]]}]}, {"n": 24, "title": "Most General Unifier and the Occur Check", "dur": 80780, "clicks": [9160, 20925, 33030, 50820, 58085], "segs": [{"click": 0, "sents": [[500, "Sometimes there is more than one unifier."], [3810, "Unify Knows of John comma x with Knows of y comma z."]]}, {"click": 1, "sents": [[9685, "Theta one says y becomes John and x becomes z."], [14485, "The result is Knows of John comma z: John knows someone, still unspecified."]]}, {"click": 2, "sents": [[21405, "Theta two says y, x, and z all become John."], [26215, "The result is Knows of John comma John."], [29615, "That also works, but it commits to more than we need."]]}, {"click": 3, "sents": [[33345, "The most general unifier, or M G U, is the one that commits to the fewest values."], [40175, "Here that is theta one."], [42665, "Unify always returns the most general unifier, because a more specific answer could rule out conclusions we need later."]]}, {"click": 4, "sents": [[51365, "One more safety check."], [53235, "What happens if we unify S of x with S of F of x?"]]}, {"click": 5, "sents": [[58665, "Binding x to F of x would mean x equals F of F of F of F, forever: an infinite term."], [67885, "So before binding a variable to a term, the algorithm checks that the variable does not occur inside that term."], [75625, "If it does, unification fails."], [78625, "This is called the occur check."]]}]}, {"n": 25, "title": "Generalized Modus Ponens (GMP)", "dur": 60090, "clicks": [15850, 27300, 46520], "segs": [{"click": 0, "sents": [[305, "Now we combine unification with Modus Ponens."], [4395, "Ordinary Modus Ponens from Chapter 7 says: if P implies Q, and P is true, conclude Q."], [12765, "But the fact must match the rule exactly."]]}, {"click": 1, "sents": [[16365, "Generalized Modus Ponens relaxes this."], [19645, "The facts only need to match the rule after a substitution theta."], [24255, "And unification is how we find theta."]]}, {"click": 2, "sents": [[27665, "Formally: we have a rule with premises p one through p n, and conclusion q."], [34415, "We have facts p one prime through p n prime."], [38295, "If a substitution theta makes each premise identical to its fact, then we may conclude theta applied to q."]]}, {"click": 3, "sents": [[47030, "The key word is one."], [49070, "The same theta must work for all the premises at once."], [53100, "If premise one needs x to be John and premise two needs x to be Richard, the rule does not fire."]]}]}, {"n": 26, "title": "GMP Step by Step: The Evil Kings Again", "dur": 66130, "clicks": [17785, 25575, 43895, 53245], "segs": [{"click": 0, "sents": [[320, "Let us trace Generalized Modus Ponens."], [3620, "The rule: if x is a king and x is greedy, then x is evil."], [9390, "The facts: John is a king, and Greedy of y."], [13240, "Since y is a variable, that fact means everyone is greedy."]]}, {"click": 1, "sents": [[18260, "Premise one."], [19700, "Unify King of x with King of John."], [22910, "Theta is x slash John."]]}, {"click": 2, "sents": [[26030, "Premise two."], [27360, "Unify Greedy of x with Greedy of y, remembering that x is already John."], [33370, "So we unify Greedy of John with Greedy of y, and y becomes John."], [39090, "Theta is still consistent: x slash John, y slash John."]]}, {"click": 3, "sents": [[44170, "Every premise matched with one theta."], [47000, "So we apply theta to the conclusion, Evil of x, and get: Evil of John."]]}, {"click": 4, "sents": [[53540, "Notice that no instance for Richard was ever generated."], [57720, "We computed only the substitution we actually needed."], [61590, "That is the efficiency gain of lifting inference to first-order logic."]]}]}, {"n": 27, "title": "Northgate Hospital: Unifying a Medication-Alert Rule", "dur": 76410, "clicks": [22820, 38460, 49790, 58090], "segs": [{"click": 0, "sents": [[400, "Back to Northgate Hospital."], [2440, "Rule R four is a medication safety rule."], [5820, "If patient p has been prescribed drug d, and d is a beta-lactam antibiotic, the family that includes penicillins, and p has a penicillin allergy, then raise an alert about giving d to p."], [20210, "The gray lines define each predicate."]]}, {"click": 1, "sents": [[23130, "Premise one."], [24510, "Unify Prescribed of p comma d with the fact in Maria's chart, Prescribed of Maria comma Amoxicillin."], [33350, "Theta: p becomes Maria and d becomes Amoxicillin."]]}, {"click": 2, "sents": [[38765, "Premise two, with theta applied, becomes BetaLactam of Amoxicillin."], [44995, "That fact is in the knowledge base."], [47355, "Same theta, consistent."]]}, {"click": 3, "sents": [[50275, "Premise three becomes PenicillinAllergy of Maria."], [54395, "That is in her chart too."], [56305, "Still the same theta."]]}, {"click": 4, "sents": [[58535, "All three premises match with one theta, so Generalized Modus Ponens fires: Alert of Maria comma Amoxicillin."], [68345, "The system warns the care team."], [70765, "One rule was matched directly, with no grounding of the other four hundred patients."]]}]}, {"n": 28, "title": "Check Your Understanding", "dur": 39000, "clicks": [13370], "segs": [{"click": 0, "sents": [[365, "Check your understanding."], [2475, "What is the result of unifying Owns of x comma Car of x, with Owns of Ana comma y?"], [9895, "Work it column by column, exactly as we did."]]}, {"click": 1, "sents": [[13885, "The answer is B."], [15775, "Argument one: x meets Ana, so x becomes Ana."], [20405, "Argument two: Car of x meets y."], [23775, "We replace x with its value first, giving Car of Ana, and bind y to Car of Ana."], [30545, "Option A is close, but it leaves the x unreplaced inside the value, so the two sentences would not come out identical."]]}]}, {"n": 29, "title": "Forward Chaining", "dur": 37960, "clicks": [15825, 23355, 30830], "segs": [{"click": 0, "sents": [[285, "Section 9.3, forward chaining."], [3965, "Now that we have Generalized Modus Ponens, we can build a complete algorithm around it."], [9995, "Forward chaining is data-driven: start from what you know and keep applying rules."]]}, {"click": 1, "sents": [[16275, "First, the kind of sentences it works on, called definite clauses, and the full Crime knowledge base."]]}, {"click": 2, "sents": [[23655, "Second, we trace the algorithm iteration by iteration until Colonel West is proven a criminal."]]}, {"click": 3, "sents": [[31485, "Third, its properties, how to make it efficient, and the Northgate medication alert."]]}]}, {"n": 30, "title": "Definite Clauses: The Sentences FC Works With", "dur": 65000, "clicks": [13130, 20610, 29710, 36085, 48790], "segs": [{"click": 0, "sents": [[295, "Forward chaining works on a special kind of sentence called a definite clause."], [5665, "It has this shape: p one and p two and so on up to p n, implies q."]]}, {"click": 1, "sents": [[13465, "The left side is a conjunction of atomic sentences, joined by AND."], [18755, "These are the premises."]]}, {"click": 2, "sents": [[21075, "The right side is exactly one atomic sentence, the conclusion."], [25965, "One, not two, and not a negation."]]}, {"click": 3, "sents": [[30195, "Variables are implicitly for all."], [33165, "We simply leave the for-all symbol off."]]}, {"click": 4, "sents": [[36585, "Examples."], [37765, "A fact is a definite clause with no premises at all, such as American of West."], [44185, "A simple rule: if x is a missile, then x is a weapon."]]}, {"click": 5, "sents": [[49085, "And here is something that is not a definite clause: P implies Q or R."], [55165, "It has two possible conclusions."], [57555, "Forward chaining cannot handle it."], [60025, "We will need resolution, in Section 9.5, for sentences like that."]]}]}, {"n": 31, "title": "The Crime KB: From English to Logic", "dur": 87310, "clicks": [10915, 29760, 45020, 57300, 65105, 75565, 82975], "segs": [{"click": 0, "sents": [[425, "Here is the whole Crime knowledge base, translated from English to logic one sentence at a time."], [7115, "Watch how each English sentence becomes a definite clause."]]}, {"click": 1, "sents": [[11315, "It is a crime for an American to sell weapons to hostile nations."], [16005, "Rule R one: if x is American, y is a weapon, x sells y to z, and z is hostile, then x is a criminal."], [27135, "Four premises, one conclusion."]]}, {"click": 2, "sents": [[30175, "Nono owns some missiles."], [32485, "That is a there-exists, so we use Existential Instantiation and name one missile M one."], [39875, "Two facts: Nono owns M one, and M one is a missile."]]}, {"click": 3, "sents": [[45645, "All of Nono's missiles were sold to it by Colonel West."], [49825, "Rule R two: if x is a missile and Nono owns x, then West sells x to Nono."]]}, {"click": 4, "sents": [[57635, "Missiles are weapons."], [59705, "Rule R three: if x is a missile, then x is a weapon."]]}, {"click": 5, "sents": [[65615, "An enemy of America counts as hostile."], [69185, "Rule R four: if x is an enemy of America, then x is hostile."]]}, {"click": 6, "sents": [[76125, "Finally two facts: West is American, and Nono is an enemy of America."]]}, {"click": 7, "sents": [[83585, "Our goal: is Criminal of West entailed?"]]}]}, {"n": 32, "title": "Forward Chaining: The Algorithm (FOL-FC-ASK)", "dur": 66560, "clicks": [8915, 13145, 25970, 34810, 42470, 49130], "segs": [{"click": 0, "sents": [[465, "Here is the forward chaining algorithm, which the textbook calls F O L, F C, ASK."], [7555, "Six steps."]]}, {"click": 1, "sents": [[9370, "Step one: start with all the known facts."]]}, {"click": 2, "sents": [[13630, "Step two: look at every rule and ask: can all of its premises be unified with known facts, using one consistent theta?"], [23090, "That is Generalized Modus Ponens."]]}, {"click": 3, "sents": [[26290, "Step three: if yes, the rule fires, and we add its conclusion, with theta applied, as a new fact."]]}, {"click": 4, "sents": [[35320, "Step four: only add it if it is genuinely new."], [39700, "If we already know it, ignore it."]]}, {"click": 5, "sents": [[43020, "Step five: if the new fact matches the goal, we are done."], [47830, "Success."]]}, {"click": 6, "sents": [[49660, "Step six: if a full pass through all the rules adds nothing new, we have reached a fixed point."], [56990, "Nothing more can ever be derived, so we stop: the goal is not entailed."], [62820, "One complete pass through the rules is called an iteration."]]}]}, {"n": 33, "title": "FC Trace, Iteration 1: Three Rules Fire", "dur": 72410, "clicks": [13270, 23905, 39430, 50185, 62025], "segs": [{"click": 0, "sents": [[320, "Let us trace forward chaining."], [2720, "On the left are our four rules."], [5360, "On the right is the knowledge base, which starts with the four facts."], [9790, "Iteration one: we try every rule."]]}, {"click": 1, "sents": [[13830, "Rule R one, the crime rule, needs Weapon of y, Sells, and Hostile of z."], [20700, "None of those are known yet."], [22500, "It cannot fire."]]}, {"click": 2, "sents": [[24260, "Rule R two: Missile of x and Owns of Nono comma x."], [29920, "Both unify with known facts using x slash M one."], [34230, "The rule fires, and we add a new fact: West sells M one to Nono."]]}, {"click": 3, "sents": [[39770, "Rule R three: Missile of x."], [43170, "Unifies with Missile of M one."], [46090, "Fires."], [47160, "New fact: M one is a weapon."]]}, {"click": 4, "sents": [[50720, "Rule R four: Enemy of x comma America."], [55100, "Unifies with x slash Nono."], [57880, "Fires."], [58990, "New fact: Nono is hostile."]]}, {"click": 5, "sents": [[62550, "End of iteration one."], [64520, "Three new facts were added, highlighted in the knowledge base."], [68390, "The goal is not derived yet, so we run another iteration."]]}]}, {"n": 34, "title": "FC Trace, Iteration 2: The Crime Rule Fires", "dur": 79820, "clicks": [16025, 23925, 34110, 50315, 59285], "segs": [{"click": 0, "sents": [[290, "Iteration two."], [2000, "Rules two, three, and four would only re-derive facts we already have, so the interesting one is the crime rule, R one."], [11470, "Watch theta grow as we match each premise, from left to right."]]}, {"click": 1, "sents": [[16470, "Premise one: American of x unifies with American of West."], [22070, "x becomes West."]]}, {"click": 2, "sents": [[24230, "Premise two: Weapon of y unifies with Weapon of M one, a fact we derived in iteration one."], [32110, "y becomes M one."]]}, {"click": 3, "sents": [[34450, "Premise three: Sells of x comma y comma z."], [38870, "With theta applied, that is Sells of West comma M one comma z."], [44220, "It unifies with Sells of West comma M one comma Nono."], [48560, "z becomes Nono."]]}, {"click": 4, "sents": [[50670, "Premise four: Hostile of z, which is now Hostile of Nono."], [55630, "That fact is known."], [57310, "Theta stays consistent."]]}, {"click": 5, "sents": [[59610, "All four premises matched with one theta: x slash West, y slash M one, z slash Nono."], [68010, "The rule fires and adds Criminal of West."], [71360, "That is our goal."], [73150, "Starting from raw facts, forward chaining proved that Colonel West is a criminal in two iterations."]]}]}, {"n": 35, "title": "The Forward-Chaining Proof Tree (built bottom-up)", "dur": 44040, "clicks": [9575, 27685], "segs": [{"click": 0, "sents": [[460, "Here is the same proof drawn as a tree."], [3460, "Forward chaining builds it from the bottom up."], [6560, "At the bottom are the four original facts."]]}, {"click": 1, "sents": [[9940, "Iteration one adds the middle level: Weapon of M one comes from Missile of M one."], [16530, "Sells comes from Missile and Owns."], [19700, "Hostile of Nono comes from Enemy."], [22540, "Follow the arrows: each new fact points back to the facts that produced it."]]}, {"click": 2, "sents": [[28130, "Iteration two adds the top: Criminal of West, supported by American of West and the three facts from level one."], [36820, "Data flows upward, from facts toward the goal."], [40730, "That is why forward chaining is called data-driven."]]}]}, {"n": 36, "title": "Forward Chaining: Properties", "dur": 67740, "clicks": [5500, 14680, 23300, 37710, 52180], "segs": [{"click": 0, "sents": [[370, "What can we say about forward chaining in general?"], [3820, "Five properties."]]}, {"click": 1, "sents": [[5980, "It is sound."], [7480, "Every step is Generalized Modus Ponens, which is valid, so it never produces a false conclusion."]]}, {"click": 2, "sents": [[14960, "It is complete for definite clauses."], [17930, "If an atomic sentence is entailed, forward chaining will eventually derive it."]]}, {"click": 3, "sents": [[23825, "It always terminates for Datalog knowledge bases, which have no function symbols."], [29275, "There are only finitely many possible facts, so it must reach a fixed point."], [35125, "Our Crime knowledge base is Datalog."]]}, {"click": 4, "sents": [[38045, "With function symbols it may not terminate."], [41075, "For example: zero is a natural number, and if n is a natural number so is the successor of n."], [48795, "Forward chaining will generate natural numbers forever."]]}, {"click": 5, "sents": [[52485, "And it derives irrelevant facts."], [55215, "It derives everything it can, whether or not it helps answer the question."], [60095, "In a large knowledge base, that wastes a lot of work."], [64175, "Backward chaining, next section, fixes that."]]}]}, {"n": 37, "title": "Making Forward Chaining Efficient", "dur": 62920, "clicks": [4910, 21790, 42060, 54360], "segs": [{"click": 0, "sents": [[295, "Real systems use three ideas to make forward chaining fast."]]}, {"click": 1, "sents": [[5385, "One: match smarter."], [8105, "Index facts by predicate so you only look at relevant facts, and match the most constrained premise first, the one with the fewest matching facts."], [18215, "It is like solving the hardest Sudoku cell first."]]}, {"click": 2, "sents": [[22275, "Two: incremental forward chaining."], [25385, "In each iteration, only try rules that have a premise matching a fact that was new in the previous iteration."], [32775, "Nothing else can produce anything new."], [35515, "Real systems use a structure called the Rete network to remember partial matches between iterations."]]}, {"click": 3, "sents": [[42405, "Three: ignore the irrelevant."], [45645, "Restrict forward chaining to rules that can actually lead to the goal, or switch direction entirely and use backward chaining."]]}, {"click": 4, "sents": [[54945, "These ideas power business-rule engines, complex-event processing, and clinical alerting systems like the one at Northgate."]]}]}, {"n": 38, "title": "Northgate Hospital: Forward Chaining Maria's Chart", "dur": 84880, "clicks": [23585, 34625, 42715, 54560, 67210], "segs": [{"click": 0, "sents": [[300, "Now Northgate."], [1960, "Four rules on the left: R one flags sepsis risk, R two orders a lactate test for anyone at sepsis risk, R three says penicillins are beta-lactams, and R four is the medication alert."], [18230, "On the right, Maria's chart."], [20870, "Amox is short for amoxicillin."]]}, {"click": 1, "sents": [[24090, "Iteration one."], [25720, "R one: Fever and High Heart Rate both match with p slash Maria."], [31350, "New fact: Maria is at sepsis risk."]]}, {"click": 2, "sents": [[34950, "Also in iteration one, R three: amoxicillin is a penicillin, so it is a beta-lactam."]]}, {"click": 3, "sents": [[43260, "Iteration two."], [44860, "R two can now fire, because Sepsis Risk of Maria was derived in iteration one."], [51030, "New fact: Maria needs a lactate test."]]}, {"click": 4, "sents": [[55020, "And R four fires: amoxicillin is prescribed, it is a beta-lactam, and Maria has a penicillin allergy."], [63450, "New fact: Alert of Maria comma Amox."]]}, {"click": 5, "sents": [[67510, "Iteration three adds nothing new, so we have reached a fixed point."], [72740, "The system orders a lactate test and alerts the care team."], [77100, "This is exactly how rule-based clinical alerting works: new data arrives, and rules fire forward."]]}]}, {"n": 39, "title": "Check Your Understanding", "dur": 29930, "clicks": [8800], "segs": [{"click": 0, "sents": [[350, "Check your understanding."], [2320, "In the Northgate trace, why did the alert rule, R four, not fire in iteration one?"]]}, {"click": 1, "sents": [[9100, "The answer is B."], [10930, "Beta Lactam of Amox was not a known fact at the start of iteration one; rule R three derived it during that iteration."], [20410, "It became available in iteration two, so R four fired then."], [25580, "Option D is false: two rules fired in iteration one."]]}]}, {"n": 40, "title": "Backward Chaining", "dur": 35090, "clicks": [15265, 19320, 25700], "segs": [{"click": 0, "sents": [[835, "Section 9.4, backward chaining."], [4655, "Forward chaining starts from facts and derives everything."], [8685, "Backward chaining does the opposite: it starts from the question and only explores what could help answer it."]]}, {"click": 1, "sents": [[15545, "First, the idea, with an everyday analogy."]]}, {"click": 2, "sents": [[19855, "Second, we grow the proof tree for Criminal of West, one subgoal at a time."]]}, {"click": 3, "sents": [[26215, "Third, we see how Prolog implements this, why it behaves like depth-first search, and how it compares with forward chaining."]]}]}, {"n": 41, "title": "The Idea: Work Backward From the Question", "dur": 53850, "clicks": [11135, 15505, 21295, 27110, 35720, 42265], "segs": [{"click": 0, "sents": [[735, "Backward chaining starts with the question and asks: what would have to be true for this goal to hold?"], [7445, "Then it proves those things in exactly the same way."]]}, {"click": 1, "sents": [[11355, "An everyday example."], [13215, "Your goal is to bake a cake."]]}, {"click": 2, "sents": [[15935, "To bake a cake you need batter and a hot oven."], [19405, "Those are subgoals."]]}, {"click": 3, "sents": [[21755, "To make batter you need flour, eggs, and sugar."], [25645, "More subgoals."]]}, {"click": 4, "sents": [[27550, "And you check: they are all in the pantry."], [30670, "Those are known facts, so the chain is complete."], [34190, "You can bake the cake."]]}, {"click": 5, "sents": [[36020, "Forward chaining goes from facts to the goal, and derives everything it can along the way."]]}, {"click": 6, "sents": [[42510, "Backward chaining goes from the goal down to subgoals and finally to facts."], [48110, "It explores only what the goal needs."], [50920, "You never check whether you could also make soup."]]}]}, {"n": 42, "title": "Backward Chaining: The Algorithm", "dur": 57630, "clicks": [3970, 8240, 17170, 28570, 37385, 45695], "segs": [{"click": 0, "sents": [[270, "Here is the backward chaining algorithm in six steps."]]}, {"click": 1, "sents": [[4410, "Step one: put the query on a list of goals."]]}, {"click": 2, "sents": [[8660, "Step two: take the first goal."], [11630, "If it unifies with a known fact, it is solved."], [15220, "Record the substitution."]]}, {"click": 3, "sents": [[17430, "Step three: otherwise, find a rule whose conclusion unifies with the goal."], [23680, "This is an OR choice: any one rule that works is enough."]]}, {"click": 4, "sents": [[29100, "Step four: replace the goal with that rule's premises."], [33310, "This is an AND: every premise must be proved."]]}, {"click": 5, "sents": [[37715, "Step five: prove each new subgoal in the same way, depth-first, carrying the substitution forward."]]}, {"click": 6, "sents": [[46255, "Step six: if a subgoal fails, backtrack and try the next rule."], [51725, "Because of the OR and AND choices, the textbook calls this an AND-OR search."]]}]}, {"n": 43, "title": "Growing the Backward-Chaining Proof Tree", "dur": 120390, "clicks": [7590, 33175, 41450, 53910, 66210, 85775, 89075, 100860], "segs": [{"click": 0, "sents": [[295, "Let us grow the backward chaining proof tree."], [3505, "We start at the top with the goal: is West a criminal?"]]}, {"click": 1, "sents": [[8115, "Which rule concludes Criminal?"], [10305, "Rule R one."], [11795, "Its conclusion, Criminal of x, unifies with our goal using x slash West."], [18045, "So the goal is replaced by R one's four premises, with x already set to West: American of West, Weapon of y, Sells of West comma y comma z, and Hostile of z."], [31105, "All four must be proven."]]}, {"click": 2, "sents": [[33515, "Subgoal one, American of West."], [36775, "That is a known fact."], [38645, "Proven immediately."], [40345, "A green check."]]}, {"click": 3, "sents": [[42165, "Subgoal two, Weapon of y."], [45365, "Not a fact, but rule R three concludes Weapon."], [49635, "Its premise becomes a new subgoal: Missile of y."]]}, {"click": 4, "sents": [[54505, "Missile of y unifies with the fact Missile of M one, so y becomes M one."], [61365, "Subgoal two is proven, and that value of y is carried to the right."]]}, {"click": 5, "sents": [[66465, "Subgoal three, now Sells of West comma M one comma z."], [72195, "Rule R two concludes Sells of West comma x comma Nono, so z becomes Nono, and we get two new subgoals: Missile of M one, and Nono owns M one."]]}, {"click": 6, "sents": [[86105, "Both are known facts."], [88035, "Proven."]]}, {"click": 7, "sents": [[89595, "Subgoal four, now Hostile of Nono."], [93285, "Rule R four reduces it to Enemy of Nono comma America, which is a known fact."], [100015, "Proven."]]}, {"click": 8, "sents": [[101165, "Every leaf of the tree is a known fact, so the root is proven."], [106445, "Criminal of West, with theta x slash West, y slash M one, z slash Nono."], [114555, "Notice: backward chaining never touched anything that was not relevant to this question."]]}]}, {"n": 44, "title": "Backward Chaining = Depth-First Search with a Stack", "dur": 75360, "clicks": [6110, 10930, 17925, 24970, 39270], "segs": [{"click": 0, "sents": [[285, "Under the hood, the list of goals behaves like a stack: last in, first out."]]}, {"click": 1, "sents": [[6375, "At time zero the stack holds the query, Criminal of West."]]}, {"click": 2, "sents": [[11385, "We pop it and push R one's four premises."], [15075, "American of West is now on top."]]}, {"click": 3, "sents": [[18455, "American of West is a fact, so we pop it."], [22265, "Weapon of y is now on top."]]}, {"click": 4, "sents": [[25505, "We replace Weapon of y with Missile of y."], [29605, "The top goal is always worked on first, so the search dives deep before it goes wide."], [35835, "That is exactly depth-first search on the proof tree."]]}, {"click": 5, "sents": [[39575, "Depth-first search has a famous danger: infinite loops."], [44305, "Look at this rule: there is a path from x to z if there is a path from x to y and a link from y to z."], [53225, "To prove Path of A comma C, the first subgoal is Path of A comma y, whose first subgoal is Path of A comma y prime, and so on forever."], [64625, "The fixes are to check for repeated goals, reorder the premises so the link is checked first, or remember goals already solved, a technique called tabling."]]}]}, {"n": 45, "title": "Prolog: Backward Chaining as a Programming Language", "dur": 48230, "clicks": [16390, 27610], "segs": [{"click": 0, "sents": [[955, "Backward chaining is the engine inside Prolog, the most widely used logic programming language."], [7525, "Here is the Crime knowledge base written in Prolog."], [10635, "Facts end with a period."], [12875, "Rules use colon-dash, which means if."]]}, {"click": 1, "sents": [[16645, "We type the query: criminal of Who?"], [20195, "Prolog answers: Who equals west."], [23725, "It found the substitution, just as our proof tree did."]]}, {"click": 2, "sents": [[28175, "How to read it: head colon-dash body means the body implies the head."], [34655, "So the conclusion is written first."], [37305, "Capital letters are variables."], [39765, "And when you ask a query, Prolog runs exactly the backward chaining trace we just did by hand, depth-first, left to right."]]}]}, {"n": 46, "title": "Prolog Is Practical — but Not Pure Logic", "dur": 67310, "clicks": [7830, 20745, 33695, 47785, 56150], "segs": [{"click": 0, "sents": [[295, "Prolog is extremely practical, but it is not pure first-order logic."], [5925, "Four differences matter."]]}, {"click": 1, "sents": [[8335, "First, the closed-world assumption."], [11615, "Anything Prolog cannot prove is treated as false."], [15485, "In pure first-order logic, something we cannot prove is simply unknown."]]}, {"click": 2, "sents": [[21235, "Second, negation as failure."], [24355, "Not P succeeds whenever P cannot be proven."], [28185, "That is useful, but it is not the same as the logical statement that P is false."]]}, {"click": 3, "sents": [[33985, "Third, clause order matters."], [37015, "Prolog always searches depth-first, left to right, top to bottom."], [42175, "Put the clauses in a bad order and it can loop forever, even when the answer exists."]]}, {"click": 4, "sents": [[48240, "Fourth, Prolog skips the occur check for speed, so in rare cases it can give unsound answers."]]}, {"click": 5, "sents": [[56690, "Despite these differences, Prolog has been used for natural language processing, expert systems, scheduling, type checkers, and parts of I B M Watson."]]}]}, {"n": 47, "title": "Forward vs Backward Chaining", "dur": 57830, "clicks": [5585, 11745, 19535, 26065, 33625, 41875], "segs": [{"click": 0, "sents": [[360, "Let us compare the two algorithms side by side, one row at a time."]]}, {"click": 1, "sents": [[6140, "Forward chaining starts from known facts."], [9340, "Backward chaining starts from the goal."]]}, {"click": 2, "sents": [[12550, "Forward goes from facts to conclusions."], [15820, "Backward goes from the goal to supporting facts."]]}, {"click": 3, "sents": [[20070, "Forward derives everything it can."], [22760, "Backward derives only what the goal needs."]]}, {"click": 4, "sents": [[26550, "Forward makes repeated passes over the rules."], [30270, "Backward searches depth-first with a goal stack."]]}, {"click": 5, "sents": [[33950, "Forward risks wasted work on irrelevant facts."], [38100, "Backward risks infinite loops on recursive rules."]]}, {"click": 6, "sents": [[42125, "Forward is typical for alerting, monitoring, and rule engines, where new data keeps arriving."], [48835, "Backward is typical for answering specific questions, diagnosis, and Prolog."], [54295, "And both are sound and complete for definite clauses."]]}]}, {"n": 48, "title": "Northgate Hospital: Asking a Question Backward", "dur": 81140, "clicks": [18155, 21015, 34010, 43105, 54180, 59310, 66380], "segs": [{"click": 0, "sents": [[325, "Now a different situation at Northgate."], [3495, "A pharmacist asks a specific question: is there any drug alert for Maria?"], [9415, "The query is Alert of Maria comma d, where d is a variable."], [15575, "We want to know which drug, if any."]]}, {"click": 1, "sents": [[18455, "The goal goes at the top of the tree."]]}, {"click": 2, "sents": [[21395, "Rule R four concludes Alert, so the goal becomes three subgoals: Maria is prescribed some drug d, d is a beta-lactam, and Maria has a penicillin allergy."]]}, {"click": 3, "sents": [[34395, "First subgoal: Prescribed of Maria comma d unifies with a fact in her chart."], [41125, "d becomes Amox."]]}, {"click": 4, "sents": [[43395, "Second subgoal, now Beta Lactam of Amox."], [47735, "Not a fact, but rule R three reduces it to Penicillin of Amox, which is a fact."]]}, {"click": 5, "sents": [[54475, "Third subgoal: Penicillin Allergy of Maria is in her chart."]]}, {"click": 6, "sents": [[59785, "All proven."], [61215, "The answer: d equals amoxicillin."], [64895, "There is an alert."]]}, {"click": 7, "sents": [[66835, "Notice that backward chaining never looked at the sepsis rules, or at any other patient."], [73005, "It explored only what this question needed."], [76235, "That focus is why question-answering systems prefer backward chaining."]]}]}, {"n": 49, "title": "Check Your Understanding", "dur": 25200, "clicks": [7740], "segs": [{"click": 0, "sents": [[695, "Check your understanding."], [2625, "Which data structure best describes how backward chaining manages its goals?"]]}, {"click": 1, "sents": [[8025, "The answer is B, a stack."], [10965, "The newest subgoals, the premises just pushed, are always worked on first."], [16665, "That is depth-first search, and depth-first search uses a stack."], [21915, "A queue would give breadth-first search instead."]]}]}, {"n": 50, "title": "Resolution", "dur": 35850, "clicks": [14905, 18785, 26950], "segs": [{"click": 0, "sents": [[515, "Section 9.5, resolution."], [4015, "This is the most general method in the chapter."], [7185, "Forward and backward chaining only work on definite clauses."], [11205, "Resolution works on any first-order sentence at all."]]}, {"click": 1, "sents": [[15195, "First, why we need something more general."]]}, {"click": 2, "sents": [[19015, "Second, how to convert any sentence into a standard form called conjunctive normal form, one step at a time."]]}, {"click": 3, "sents": [[27265, "Third, the resolution rule itself, and a proof that Colonel West is a criminal, our third proof of the same fact."]]}]}, {"n": 51, "title": "Why We Need More Than Definite Clauses", "dur": 52130, "clicks": [10230, 21470, 29230, 38905], "segs": [{"click": 0, "sents": [[475, "Some knowledge cannot be written as premises implying one positive conclusion."], [5815, "Forward and backward chaining cannot use it."], [8925, "Three examples."]]}, {"click": 1, "sents": [[10605, "A disjunction."], [12215, "Maria's infection is bacterial or viral."], [15705, "We do not know which, so there is no single conclusion to put on the right side of a rule."]]}, {"click": 2, "sents": [[21965, "A negative fact."], [23615, "Maria is not pregnant."], [25955, "Definite clauses cannot state negations."]]}, {"click": 3, "sents": [[29695, "An existential inside a universal."], [33145, "Every patient has some attending doctor."], [36205, "We need Skolem functions to handle it."]]}, {"click": 4, "sents": [[39355, "Resolution handles all of these."], [41935, "The plan has three steps: convert every sentence to conjunctive normal form, add the negation of the goal, and resolve until a contradiction appears."]]}]}, {"n": 52, "title": "Conjunctive Normal Form (CNF): The Vocabulary", "dur": 70890, "clicks": [8750, 18550, 27280, 40225, 51475, 56905], "segs": [{"click": 0, "sents": [[305, "Resolution works on a standard form called conjunctive normal form, or C N F."], [7225, "Three words to learn."]]}, {"click": 1, "sents": [[9065, "A literal is an atom, or the negation of an atom."], [13235, "Missile of x is a literal."], [15775, "Not Hostile of z is a literal."]]}, {"click": 2, "sents": [[18875, "A clause is a set of literals joined by OR."], [22505, "For example: not Missile of x, or Weapon of x."]]}, {"click": 3, "sents": [[27855, "A sentence in conjunctive normal form is a set of clauses joined by AND."], [33205, "So: ANDs of ORs."], [35845, "Conjunctive means AND, and each conjunct is a clause."]]}, {"click": 4, "sents": [[40730, "Here is something useful."], [42590, "Every definite clause is already a CNF clause in disguise."], [47080, "Take: Missile of x implies Weapon of x."]]}, {"click": 5, "sents": [[51820, "It is equivalent to: not Missile of x, or Weapon of x."]]}, {"click": 6, "sents": [[57430, "Why?"], [58380, "P implies Q is false only when P is true and Q is false."], [64160, "And not P or Q is false in exactly the same case."], [68900, "So they always agree."]]}]}, {"n": 53, "title": "CNF Conversion, Steps 1–3", "dur": 81370, "clicks": [27670, 45140, 70730], "segs": [{"click": 0, "sents": [[330, "Let us convert a real sentence, step by step."], [3880, "The sentence says: everyone who loves all animals is loved by someone."], [9380, "In logic: for all x, if for all y, y being an animal implies x loves y, then there exists a y who loves x."], [20120, "It has two implications, nested quantifiers, everything."], [24630, "Six steps will turn it into CNF."]]}, {"click": 1, "sents": [[28000, "Step one: remove the implications."], [31270, "Every P implies Q becomes not P or Q."], [36120, "There are two implications here, so we do it twice."], [39810, "The inner one becomes not Animal of y or Loves x y."]]}, {"click": 2, "sents": [[45480, "Step two: move negations inward until they sit directly on atoms."], [51280, "Not for-all y becomes there-exists y not."], [55650, "Not of an OR becomes an AND of nots, by De Morgan's law."], [60980, "And two nots cancel."], [63110, "Now we read: for all x, either there is some animal x does not love, or someone loves x."]]}, {"click": 3, "sents": [[71250, "Step three: rename variables so each quantifier has its own."], [76470, "The second y becomes z."], [77980, "This prevents confusion in the next step."]]}]}, {"n": 54, "title": "CNF Conversion, Steps 4–6", "dur": 57780, "clicks": [2365, 20105, 29995, 43390], "segs": [{"click": 0, "sents": [[270, "We continue from step three."]]}, {"click": 1, "sents": [[2760, "Step four: Skolemize."], [5370, "Both there-exists sit inside the for-all x, so we use Skolem functions."], [11400, "y becomes F of x, the animal that x fails to love."], [16020, "z becomes G of x, the someone who loves x."]]}, {"click": 2, "sents": [[20470, "Step five: drop the for-all."], [23800, "Every remaining variable is understood as for all, so the symbol is no longer needed."]]}, {"click": 3, "sents": [[30690, "Step six: distribute OR over AND."], [34730, "A and B, or C, becomes A or C, and B or C."], [40920, "Now we have ANDs of ORs."]]}, {"click": 4, "sents": [[43680, "The result is two clauses joined by AND."], [47140, "That is conjunctive normal form."], [49890, "The same six steps convert any first-order sentence, which is why resolution can handle all of first-order logic."]]}]}, {"n": 55, "title": "The Resolution Rule", "dur": 65060, "clicks": [17085, 29590, 39495, 51025], "segs": [{"click": 0, "sents": [[290, "The resolution rule in plain language: take two clauses that contain a complementary pair, a literal and its negation that can be unified."], [10940, "Cancel the pair, merge everything else into one new clause, and apply the substitution."]]}, {"click": 1, "sents": [[17410, "An example."], [18830, "Clause C one: not King of x, or not Greedy of x, or Evil of x."], [26300, "Clause C two: King of John."]]}, {"click": 2, "sents": [[30160, "The complementary pair is not King of x in C one, and King of John in C two."], [36560, "They unify with x slash John."]]}, {"click": 3, "sents": [[39850, "Cancel the pair, merge what is left, apply theta."], [44620, "The new clause, called the resolvent, is: not Greedy of John, or Evil of John."]]}, {"click": 4, "sents": [[51315, "In English: if John is greedy, he is evil."], [55525, "The king condition has been used up."], [58065, "If you compare, this is exactly one step of Generalized Modus Ponens, written in a different form."]]}]}, {"n": 56, "title": "Resolution Refutation: Proof by Contradiction", "dur": 75000, "clicks": [7220, 14925, 22745, 29140, 40240, 58780], "segs": [{"click": 0, "sents": [[565, "Resolution proves things by contradiction."], [3725, "This is called refutation."], [6095, "Four steps."]]}, {"click": 1, "sents": [[7575, "Step one: assume the opposite."], [10575, "Add the negation of the goal, not alpha, to the knowledge base."]]}, {"click": 2, "sents": [[15245, "Step two: convert everything, the knowledge base plus not alpha, into CNF clauses."]]}, {"click": 3, "sents": [[23015, "Step three: repeatedly resolve pairs of clauses and add the resolvents."]]}, {"click": 4, "sents": [[29405, "Step four: if we ever produce the empty clause, we have a contradiction."], [35015, "Our assumption, not alpha, must be wrong, so alpha is proven."]]}, {"click": 5, "sents": [[40555, "What is the empty clause, drawn as a small box?"], [44505, "It is a clause with no literals left."], [47495, "It appears when we resolve P with not P."], [50975, "P and not P can never both be true, so reaching it means the knowledge base plus not alpha is impossible."]]}, {"click": 6, "sents": [[59285, "Think of a detective checking an alibi."], [61935, "Suppose the suspect is innocent."], [64205, "Follow the evidence, and it leads to an impossibility."], [67765, "Therefore the suspect is guilty."], [70175, "Resolution refutation is exactly that argument, made mechanical."]]}]}, {"n": 57, "title": "Resolution Proof: Criminal(West)", "dur": 106280, "clicks": [27815, 43810, 60270, 73490, 83575], "segs": [{"click": 0, "sents": [[340, "Let us prove Criminal of West by resolution."], [4160, "On screen are six clauses."], [6660, "C one is the crime rule in CNF."], [9970, "C two through C five are facts."], [13000, "To keep the trace short we use the facts derived earlier, but the other rules could be resolved in exactly the same way."], [20490, "C six is the negated goal: West is not a criminal."], [25080, "We will show this leads to a contradiction."]]}, {"click": 1, "sents": [[28370, "Resolution one: C one with C two."], [32100, "Not American of x cancels with American of West, with x slash West."], [38070, "The resolvent R one keeps the other four literals, with x replaced by West."]]}, {"click": 2, "sents": [[44100, "Resolution two: R one with C three."], [48120, "Not Weapon of y cancels with Weapon of M one, y slash M one."], [53950, "R two is shorter by one literal."], [57030, "A record of each step stays along the bottom."]]}, {"click": 3, "sents": [[60600, "Resolution three: R two with C four."], [64430, "The Sells literals cancel with z slash Nono."], [68360, "R three: not Hostile of Nono, or Criminal of West."]]}, {"click": 4, "sents": [[73740, "Resolution four: R three with C five."], [77800, "Hostile of Nono cancels."], [80280, "R four is just: Criminal of West."]]}, {"click": 5, "sents": [[84040, "Finally, R four with C six."], [87370, "Criminal of West and not Criminal of West cancel, leaving nothing: the empty clause."], [93690, "A contradiction."], [95090, "Our assumption that West is not a criminal must be false, so Criminal of West is proven."], [101590, "That is our third proof of the same fact, by a completely different method."]]}]}, {"n": 58, "title": "Resolution: Properties", "dur": 66060, "clicks": [2670, 8775, 16995, 34405, 44060], "segs": [{"click": 0, "sents": [[320, "Five properties of resolution."]]}, {"click": 1, "sents": [[3040, "It is sound."], [4570, "Every resolvent is entailed by its two parent clauses."]]}, {"click": 2, "sents": [[9305, "It works for all of first-order logic, not just definite clauses."], [13995, "Anything that converts to CNF."]]}, {"click": 3, "sents": [[17455, "It is refutation-complete."], [19935, "If the knowledge base entails alpha, resolution applied to the knowledge base plus not alpha is guaranteed to reach the empty clause."], [29145, "That guarantee comes from Herbrand's theorem together with the ground resolution theorem."]]}, {"click": 4, "sents": [[34875, "But if alpha is not entailed, it may run forever."], [38975, "First-order logic is still semidecidable, and no method can escape that."]]}, {"click": 5, "sents": [[44345, "And it needs strategy."], [46265, "Blindly resolving every pair is slow, so real provers use strategies such as unit preference, which resolves with single-literal clauses first; set of support, which always involves the negated goal; and subsumption, which deletes clauses that are more specific than ones we already have."]]}]}, {"n": 59, "title": "Northgate Hospital: Proving the Alert by Refutation", "dur": 63340, "clicks": [19860, 29910, 35160, 43135], "segs": [{"click": 0, "sents": [[395, "Here is the Northgate alert proven by refutation."], [4155, "C one is the alert rule in CNF."], [7245, "C two through C four come from Maria's chart, plus the derived fact that amoxicillin is a beta-lactam."], [14605, "C five is the negated goal: no alert for Maria and amoxicillin."]]}, {"click": 1, "sents": [[20235, "Resolve C one with C two."], [22935, "The Prescribed literals cancel with p slash Maria and d slash Amox, leaving three literals."]]}, {"click": 2, "sents": [[30435, "Resolve with C three."], [32645, "The Beta Lactam literals cancel."]]}, {"click": 3, "sents": [[35705, "Resolve with C four."], [37665, "The allergy literals cancel, leaving Alert of Maria comma Amox."]]}, {"click": 4, "sents": [[43395, "Resolve with C five, the negated goal."], [46955, "They cancel completely."], [49035, "The empty clause."], [50535, "The alert is proven."], [52965, "In a real hospital system, resolution earns its keep when the chart contains disjunctions, such as bacterial or viral, which chaining cannot use."]]}]}, {"n": 60, "title": "Check Your Understanding", "dur": 33370, "clicks": [10450], "segs": [{"click": 0, "sents": [[375, "Check your understanding."], [2325, "What do you get when you resolve: not Weapon of y, or Criminal of West, with Weapon of M one?"]]}, {"click": 1, "sents": [[11065, "The answer is B, Criminal of West."], [14715, "The complementary pair is not Weapon of y and Weapon of M one, with y slash M one."], [22275, "Cancel the pair and what remains is Criminal of West."], [26605, "The substitution does not touch West."], [29555, "The empty clause only appears when nothing at all is left."]]}]}, {"n": 61, "title": "Choosing an Inference Method", "dur": 66880, "clicks": [3960, 13915, 22630, 29140, 40840, 54760], "segs": [{"click": 0, "sents": [[275, "Let us compare all three methods, row by row."]]}, {"click": 1, "sents": [[4455, "Forward and backward chaining work on definite clauses."], [8625, "Resolution works on any first-order sentence, via CNF."]]}, {"click": 2, "sents": [[14435, "Forward goes from facts to goal."], [17185, "Backward goes from goal to facts."], [20105, "Resolution searches for a contradiction."]]}, {"click": 3, "sents": [[22865, "All three are complete in their setting."], [25845, "Backward chaining needs loop checking to be complete."]]}, {"click": 4, "sents": [[29425, "Termination: forward chaining always terminates on Datalog."], [34325, "Backward chaining may loop."], [36645, "Resolution may not terminate when the goal is not entailed."]]}, {"click": 5, "sents": [[41170, "Best use: forward chaining for monitoring and alerts."], [45660, "Backward chaining for answering questions, and Prolog."], [50000, "Resolution for theorem proving and verifying hardware and software."]]}, {"click": 6, "sents": [[55270, "A simple rule of thumb."], [57310, "New data arriving: forward chaining."], [60290, "A specific question: backward chaining."], [63380, "Messy or disjunctive knowledge: resolution."]]}]}, {"n": 62, "title": "Chapter 9 Summary", "dur": 73080, "clicks": [4025, 19550, 27240, 38170, 50275, 60265], "segs": [{"click": 0, "sents": [[380, "Let us summarize Chapter 9 in six ideas."]]}, {"click": 1, "sents": [[4520, "One: propositionalization."], [7300, "Universal and existential instantiation turn first-order logic into propositional logic."], [14150, "It is correct, thanks to Herbrand's theorem, but it explodes in size."]]}, {"click": 2, "sents": [[20110, "Two: unification finds the most general substitution that makes two sentences identical."]]}, {"click": 3, "sents": [[27770, "Three: Generalized Modus Ponens combines unification with Modus Ponens."], [33730, "A rule fires when one substitution matches all its premises."]]}, {"click": 4, "sents": [[38470, "Four: forward chaining is data-driven."], [41970, "It is sound and complete for definite clauses, it stops at a fixed point, and it may derive irrelevant facts."]]}, {"click": 5, "sents": [[50820, "Five: backward chaining is goal-driven and depth-first, with a stack of goals."], [56670, "It is the engine of Prolog."], [58790, "Watch out for loops."]]}, {"click": 6, "sents": [[60640, "Six: resolution converts to CNF, adds the negated goal, and resolves until the empty clause."], [68900, "It is refutation-complete for all of first-order logic."]]}]}, {"n": 63, "title": "From Reasoning to Representation", "dur": 56590, "clicks": [14470, 23050, 30080, 35390, 45860], "segs": [{"click": 0, "sents": [[560, "That completes Part one."], [2600, "We now know how a computer reasons with first-order logic."], [6840, "But the algorithms are only as good as the knowledge we give them."], [10900, "Reason about what?"], [12520, "Think about Northgate Hospital."]]}, {"click": 1, "sents": [[14750, "How should we organize categories like patient, doctor, and antibiotic, so that facts about one apply to the others?"]]}, {"click": 2, "sents": [[23370, "How do we represent time?"], [25630, "Maria's fever started at two in the morning and ended at noon."]]}, {"click": 3, "sents": [[30640, "How do we represent what the nurse knows, versus what the doctor knows?"]]}, {"click": 4, "sents": [[35910, "And what about defaults?"], [37920, "Patients normally tolerate amoxicillin, unless they are allergic."], [42720, "Classical logic has no word for normally."]]}, {"click": 5, "sents": [[46310, "These are the questions of Chapter 10, Knowledge Representation."], [51130, "Let us take a ten-minute break."], [53450, "When we come back, we start Part two."]]}]}], "p2": [{"n": 1, "title": "Knowledge Representation", "dur": 32580, "clicks": [], "segs": [{"click": 0, "sents": [[0, "Welcome back."], [1280, "In Part one we built inference engines: unification, forward chaining, backward chaining, and resolution."], [9080, "They are powerful, but an engine is only as good as the fuel you put in it."], [14230, "Part two is about that fuel."], [16750, "Chapter 10, Knowledge Representation, asks: what should an intelligent system know, and how should that knowledge be organized so that reasoning works in the messy real world?"], [27870, "As before, every idea will be built on screen one step at a time."]]}]}, {"n": 2, "title": "Part 2 Roadmap: Six Layers of Knowledge", "dur": 61450, "clicks": [8110, 16375, 25705, 32760, 41615, 51565], "segs": [{"click": 0, "sents": [[350, "Chapter 10 has six sections."], [2890, "Think of them as six layers that together make a complete knowledge architecture."]]}, {"click": 1, "sents": [[8470, "Section 10.1, ontological engineering: the overall framework of what kinds of things exist."]]}, {"click": 2, "sents": [[16690, "Section 10.2, categories and objects: classes, parts, measurements, and what the textbook calls stuff."]]}, {"click": 3, "sents": [[26010, "Section 10.3, events: how to represent actions, time, and change."]]}, {"click": 4, "sents": [[33090, "Section 10.4, mental objects and modal logic: how to represent what agents know and believe."]]}, {"click": 5, "sents": [[42100, "Section 10.5, reasoning systems: semantic networks and description logics, which make reasoning about categories fast."]]}, {"click": 6, "sents": [[51870, "Section 10.6, default reasoning: how to handle rules that have exceptions, which turns out to be almost all rules in the real world."]]}]}, {"n": 3, "title": "Why Knowledge Representation Matters", "dur": 70000, "clicks": [16050, 22090, 37100, 46960, 55715], "segs": [{"click": 0, "sents": [[330, "Why does a whole chapter exist on knowledge representation?"], [4280, "Because a perfect inference engine running on a badly organized knowledge base will still give wrong or useless answers."], [12520, "Getting the representation right is half the battle."]]}, {"click": 1, "sents": [[16620, "Here are four questions the Northgate system cannot answer with Chapter 9 alone."]]}, {"click": 2, "sents": [[22560, "Categories."], [23870, "If all penicillins can trigger Maria's allergy, does amoxicillin?"], [29080, "Is a nurse a kind of clinician?"], [31570, "We need a way to organize categories so facts flow from general to specific."]]}, {"click": 3, "sents": [[37610, "Time."], [38740, "Maria's fever started at two in the morning."], [41830, "Is she still febrile at noon?"], [44210, "We need to represent change over time."]]}, {"click": 4, "sents": [[47240, "Knowledge."], [48280, "The night nurse knows about the allergy."], [50810, "Does the pharmacist?"], [52490, "We need to represent what different agents know."]]}, {"click": 5, "sents": [[56100, "Exceptions."], [57560, "Patients usually tolerate amoxicillin, unless they are allergic."], [62420, "Classical logic has no word for usually."], [65840, "Each of these questions is answered by one section of Chapter 10."]]}]}, {"n": 4, "title": "Ontological Engineering", "dur": 37220, "clicks": [19100, 22690, 29715], "segs": [{"click": 0, "sents": [[540, "Section 10.1, ontological engineering."], [4770, "The word ontology comes from Greek: ontos, being, and logos, study."], [11330, "In AI, an ontology is a formal specification of the kinds of things that exist in a domain and how they relate."]]}, {"click": 1, "sents": [[19380, "First, what an ontology is made of."]]}, {"click": 2, "sents": [[23190, "Second, the upper ontology: the most general categories, shared by every domain."]]}, {"click": 3, "sents": [[30250, "Third, how real ontologies are built, and why building a general-purpose one is so hard."]]}]}, {"n": 5, "title": "What Is an Ontology?", "dur": 61270, "clicks": [7385, 18160, 29265, 37910], "segs": [{"click": 0, "sents": [[560, "An ontology has three components, written as the triple O equals C, R, P."]]}, {"click": 1, "sents": [[7980, "C is the set of concepts, or classes: the kinds of things that exist."], [13840, "At Northgate: Person, Patient, Doctor, Drug."]]}, {"click": 2, "sents": [[18510, "R is the set of relations: how things connect."], [22620, "Treated By connects a patient to a doctor."], [26110, "Prescribed connects a patient to a drug."]]}, {"click": 3, "sents": [[29620, "P is the set of properties: the attributes things have, such as age, ward, dose, and specialization."]]}, {"click": 4, "sents": [[38430, "The most important pattern in any ontology is this axiom: for all x, if x is a doctor, then x is a person."], [48220, "Membership in a subcategory implies membership in the parent category."], [53260, "Every major knowledge graph, from Google's to Wikidata, is built on this concepts, relations, properties structure."]]}]}, {"n": 6, "title": "The Upper Ontology: The Most General Categories", "dur": 80940, "clicks": [15285, 29590, 39890, 47900, 51810, 63485], "segs": [{"click": 0, "sents": [[330, "The upper ontology is the most general layer of a knowledge system."], [4940, "It defines the categories that appear in every domain."], [8670, "This is a simplified version of Figure 10.1 in the textbook."], [13140, "At the very top: Anything."]]}, {"click": 1, "sents": [[15490, "Anything divides into abstract objects, generalized events, and things."], [21140, "In the textbook the last branch is split directly into physical objects and stuff; we group them here to keep the picture readable."]]}, {"click": 2, "sents": [[29950, "Abstract objects include sets, numbers, and sentences."], [34860, "Generalized events include time intervals, places, and processes."]]}, {"click": 3, "sents": [[40230, "The physical side splits into physical objects, things with boundaries, and stuff, like water or butter."]]}, {"click": 4, "sents": [[48260, "Physical objects include animals and agents."]]}, {"click": 5, "sents": [[52290, "And humans sit underneath both animals and agents."], [56410, "A human is both."], [58160, "So the upper ontology is not a strict tree; categories can overlap."]]}, {"click": 6, "sents": [[63830, "Each line means: is a kind of."], [66780, "And notice why this matters."], [69050, "Every domain ontology, whether for medicine, law, or retail, hangs off this general frame."], [76280, "Get the upper layer right, and domain knowledge slots in naturally."]]}]}, {"n": 7, "title": "How Are Real Ontologies Built?", "dur": 81750, "clicks": [7355, 26085, 39125, 50410, 60765], "segs": [{"click": 0, "sents": [[620, "How are real ontologies built?"], [3300, "There are four approaches, each with a well-known example."]]}, {"click": 1, "sents": [[7940, "One: expert design."], [10530, "Knowledge engineers write the axioms by hand."], [13730, "The textbook's example is CYC, a project begun in 1984 to encode human commonsense knowledge, which now holds millions of facts."], [23320, "High quality, but very expensive."]]}, {"click": 2, "sents": [[26415, "Two: import from databases."], [29755, "DBpedia pulls categories and attributes from the structured boxes in Wikipedia articles."], [36215, "Large, but uneven in quality."]]}, {"click": 3, "sents": [[39635, "Three: extract from text."], [42255, "Systems like TextRunner read millions of web pages and pull out relations automatically."], [48285, "Huge scale, but noisy."]]}, {"click": 4, "sents": [[50755, "Four: crowdsourcing."], [53155, "OpenMind asked volunteers to type commonsense facts in plain English."], [58385, "Cheap, but inconsistent."]]}, {"click": 5, "sents": [[61125, "Tom Gruber, one of the founders of the field, made a point worth remembering: an ontology is not discovered, it is a social agreement among people who need to share knowledge."], [73295, "Northgate's doctors, pharmacists, and engineers must agree on what a patient is before the system can reason about one."]]}]}, {"n": 8, "title": "Worked Example: Inheritance Through an Ontology", "dur": 58580, "clicks": [7515, 10925, 18520, 26345, 35490, 40445], "segs": [{"click": 0, "sents": [[595, "Here is why ontologies are powerful."], [3495, "What can we conclude about Doctor Smith from just three sentences?"]]}, {"click": 1, "sents": [[7805, "Fact: Doctor Smith is a doctor."]]}, {"click": 2, "sents": [[11445, "Ontology axiom: for all x, if x is a doctor, then x is a person."]]}, {"click": 3, "sents": [[19225, "Ontology axiom: for all x, if x is a person, then x has rights."]]}, {"click": 4, "sents": [[26750, "Now chain them, exactly like forward chaining in Chapter 9."], [31260, "Doctor Smith is a doctor, so Doctor Smith is a person."]]}, {"click": 5, "sents": [[35800, "And because Doctor Smith is a person, Doctor Smith has rights."]]}, {"click": 6, "sents": [[40920, "No rule ever mentioned doctors having rights."], [44400, "The conclusion flowed down the hierarchy automatically."], [48080, "That is inheritance."], [50090, "It is also why a mistake in the hierarchy is dangerous: put a category in the wrong place, and it inherits the wrong properties."]]}]}, {"n": 9, "title": "Northgate Hospital: A Clinical Ontology", "dur": 52870, "clicks": [3820, 9665, 20105, 30345, 34275], "segs": [{"click": 0, "sents": [[490, "Let us sketch Northgate's clinical ontology."]]}, {"click": 1, "sents": [[4390, "On the people side: Persons divide into Patients and Staff."]]}, {"click": 2, "sents": [[10220, "Staff includes Clinicians, and Clinicians include Doctors and Nurses."], [15750, "So a nurse is a clinician, and a clinician is staff."]]}, {"click": 3, "sents": [[20380, "On the drug side: Drugs include Antibiotics, Antibiotics include Beta-Lactams, and Beta-Lactams include Penicillins."]]}, {"click": 4, "sents": [[30840, "And amoxicillin is a member of Penicillins."]]}, {"click": 5, "sents": [[34785, "Now one fact, Maria's penicillin allergy, combined with the hierarchy, flags every penicillin-class drug at once, including drugs added to the formulary next year."], [46675, "The rule writers never have to list them one by one."], [50035, "That is the payoff of a good ontology."]]}]}, {"n": 10, "title": "Check Your Understanding", "dur": 24590, "clicks": [7440], "segs": [{"click": 0, "sents": [[345, "Check your understanding."], [2315, "In the upper ontology, why is the hierarchy not a strict tree?"]]}, {"click": 1, "sents": [[7925, "The answer is B."], [9885, "Humans sit under both animals and agents, so one category has two parents."], [16125, "A strict tree only allows one parent per node."], [19865, "Overlapping categories are realistic, and the upper ontology allows them."]]}]}, {"n": 11, "title": "Categories and Objects", "dur": 37030, "clicks": [15500, 21625, 28285], "segs": [{"click": 0, "sents": [[385, "Section 10.2, categories and objects."], [4745, "Most reasoning happens at the level of categories: we buy an apple, not a particular apple; we prescribe a penicillin, not a particular molecule."]]}, {"click": 1, "sents": [[15845, "First, two ways to write categories in logic, and how inheritance works."]]}, {"click": 2, "sents": [[22175, "Second, how categories relate to each other, and how objects are made of parts."]]}, {"click": 3, "sents": [[28765, "Third, measurements, the difference between things and stuff, and categories that resist strict definitions."]]}]}, {"n": 12, "title": "Two Ways to Write a Category in FOL", "dur": 64290, "clicks": [4795, 28915, 51225], "segs": [{"click": 0, "sents": [[515, "There are two ways to write a category in first-order logic."]]}, {"click": 1, "sents": [[5360, "One: as a predicate."], [7730, "Basketball of B B nine says B B nine is a basketball."], [12980, "The subcategory rule is: for all x, if x is a basketball, then x is a ball."], [20580, "This is simple."], [21950, "But you cannot say anything about the category itself, because the category is not an object in the logic."]]}, {"click": 2, "sents": [[29250, "Two: as an object."], [31700, "We write B B nine is a member of Basketballs, and Basketballs is a subset of Balls."], [39020, "Now the category is a thing we can talk about."], [42050, "For example: Dogs is a member of Domesticated Species."], [46510, "That statement is about the species, not about any individual dog."]]}, {"click": 3, "sents": [[51730, "Turning something into an object so you can attach facts to it is called reification."], [57460, "We will meet it again for events."], [59600, "The textbook switches between the two notations, so learn to read both."]]}]}, {"n": 13, "title": "Inheritance Step by Step", "dur": 66720, "clicks": [18395, 23405, 28775, 34300, 42800, 48400], "segs": [{"click": 0, "sents": [[360, "Let us trace inheritance step by step."], [3830, "The hierarchy: apples are a subset of fruit, and fruit is a subset of food."], [10490, "The property: anything that is food is edible."], [14660, "And we observe: this Granny Smith is an apple."]]}, {"click": 1, "sents": [[19280, "Start with the observation: Granny Smith is an apple."]]}, {"click": 2, "sents": [[23780, "Apples are a subset of fruit, so Granny Smith is a fruit."]]}, {"click": 3, "sents": [[29290, "Fruit is a subset of food, so Granny Smith is food."]]}, {"click": 4, "sents": [[34870, "And food is edible."], [36650, "So Granny Smith is edible, derived by chaining two subset links and one property."]]}, {"click": 5, "sents": [[43135, "Classification runs the other way: from what we perceive, to a category."]]}, {"click": 6, "sents": [[48895, "If something is striped, round, with red flesh and black seeds, it is a watermelon."], [55475, "And once it is classified, it inherits everything known about watermelons, fruit, and food."], [62155, "Perception gives us the category; the hierarchy gives us the rest."]]}]}, {"n": 14, "title": "Disjoint, Exhaustive, Partition", "dur": 60230, "clicks": [5345, 15165, 32640, 43095], "segs": [{"click": 0, "sents": [[305, "Three words describe how a category's subcategories relate to each other."]]}, {"click": 1, "sents": [[5745, "Disjoint: the subcategories have no member in common."], [10705, "Animals and vegetables are disjoint."], [13585, "Nothing is both."]]}, {"click": 2, "sents": [[15505, "Exhaustive decomposition: every member of the parent is in at least one subcategory."], [22735, "Americans, Canadians, and Mexicans exhaustively decompose North Americans."], [28465, "But they are not disjoint: a dual citizen is in two."]]}, {"click": 3, "sents": [[33255, "Partition: both disjoint and exhaustive."], [37115, "Every member is in exactly one part."], [40235, "The five kingdoms partition living things."]]}, {"click": 4, "sents": [[43425, "Why does this matter?"], [45155, "If a system wrongly assumes North Americans is a partition, it will conclude that a Canadian cannot also be American, which is false for dual citizens."], [55255, "Exclusivity is a strong claim; only assert it when it is true."]]}]}, {"n": 15, "title": "Physical Composition: The PartOf Relation", "dur": 72060, "clicks": [21940, 27135, 30615, 33550, 36185, 45275, 57655], "segs": [{"click": 0, "sents": [[355, "Objects can be parts of other objects."], [3595, "The Part Of relation has two key properties."], [6935, "It is transitive: if x is part of y, and y is part of z, then x is part of z."], [14625, "And it is reflexive: every object is part of itself, a convenience that keeps the mathematics clean."]]}, {"click": 1, "sents": [[22465, "Here are stated facts."], [24635, "Bucharest is part of Romania."]]}, {"click": 2, "sents": [[27655, "Romania is part of Eastern Europe."]]}, {"click": 3, "sents": [[31155, "Eastern Europe is part of Europe."]]}, {"click": 4, "sents": [[33835, "And Europe is part of Earth."]]}, {"click": 5, "sents": [[36675, "Apply transitivity three times, and we conclude: Bucharest is part of Earth."], [42945, "We never stated that fact."]]}, {"click": 6, "sents": [[45875, "A common mistake: Part Of is not the same as subset."], [50695, "Bucharest is part of Romania, but Bucharest is an individual city, not a collection of members."]]}, {"click": 7, "sents": [[57985, "Another common mistake: a category is not a pile."], [62415, "The category Apples has no weight."], [65465, "If you want to talk about three particular apples as one object with weight, use Bunch Of."]]}]}, {"n": 16, "title": "Measurements and “Things vs Stuff”", "dur": 83320, "clicks": [6810, 26805, 40555, 60410], "segs": [{"click": 0, "sents": [[545, "Two more ideas about objects: measurements, and the difference between things and stuff."]]}, {"click": 1, "sents": [[7660, "Measures are treated as objects."], [10300, "The diameter of ball twelve equals Inches of nine point five."], [14990, "Its list price equals Dollars of nineteen."], [18320, "And unit conversion becomes a simple equality: Centimeters of two point five four times d equals Inches of d."]]}, {"click": 2, "sents": [[27150, "Because measures are objects, we can order them without knowing their values."], [32250, "If exam one is more difficult than exam two, its expected score is lower."], [38080, "This is called qualitative reasoning."]]}, {"click": 3, "sents": [[40890, "Now things versus stuff."], [43600, "Things are count nouns: one aardvark, two aardvarks."], [49070, "Cut an aardvark in half and you do not get two aardvarks."], [53500, "Properties like weight and shape are extrinsic: they belong to the whole and are lost when you divide it."]]}, {"click": 4, "sents": [[61120, "Stuff is mass nouns: butter, water, saline."], [66370, "Any part of butter is still butter, and that is the formula shown."], [71270, "Properties like density and melting point are intrinsic: they are kept when you divide it."], [77420, "A hospital system must know the difference: you count tablets, but you measure saline."]]}]}, {"n": 17, "title": "Natural Kinds: When Strict Definitions Fail", "dur": 68720, "clicks": [4960, 17525, 30630, 46290], "segs": [{"click": 0, "sents": [[360, "Some categories can be defined exactly."], [3410, "Others cannot."]]}, {"click": 1, "sents": [[5440, "Formal categories have exact definitions."], [9060, "A bachelor is, by definition, an unmarried adult male."], [14140, "The double arrow means if and only if."]]}, {"click": 2, "sents": [[18020, "Natural kinds, like tomato, bird, or game, have no exact definition."], [24620, "Most tomatoes are red and round, but some are yellow, some are green, some are tiny."]]}, {"click": 3, "sents": [[30940, "The philosopher Wittgenstein noticed that chess, tag, solitaire, and dodgeball are all games, yet there is no single feature they all share."], [41510, "Members of a natural kind share overlapping family resemblances instead."]]}, {"click": 4, "sents": [[46570, "The textbook's practical fix is to separate typical members."], [51000, "Typical of Tomatoes is a subset of Tomatoes, and the rule red and round applies only to typical tomatoes."], [59290, "We get useful rules without claiming they hold for every single member."], [64000, "This idea returns in Section 10.6 as default reasoning."]]}]}, {"n": 18, "title": "Northgate Hospital: Categories at Work", "dur": 63510, "clicks": [3610, 18735, 30115, 44335, 54575], "segs": [{"click": 0, "sents": [[400, "Here is how these ideas show up at Northgate."]]}, {"click": 1, "sents": [[4050, "Patient status is a partition: inpatients, outpatients, and discharged."], [10170, "A patient has exactly one status at a time, so the system can safely conclude that an inpatient is not discharged."]]}, {"click": 2, "sents": [[19270, "Clinician types are not a partition."], [22140, "A nurse practitioner may count as both a nurse and a prescriber."], [26540, "Marking this as a partition would cause wrong conclusions."]]}, {"click": 3, "sents": [[30380, "Part Of locates things."], [32830, "Bed twelve is part of Ward four, Ward four is part of the North Wing, so bed twelve is in the North Wing."], [40990, "The alert system uses this to page the right team."]]}, {"click": 4, "sents": [[44660, "Doses are measure objects: the dose of order seventeen equals five hundred milligrams, which the system can compare with a maximum dose."]]}, {"click": 5, "sents": [[55130, "And saline is stuff: it is measured in milliliters, not counted, and any portion of saline is still saline."]]}]}, {"n": 19, "title": "Check Your Understanding", "dur": 24290, "clicks": [6610], "segs": [{"click": 0, "sents": [[380, "Check your understanding."], [2230, "Bucharest is part of Romania."], [4690, "Which statement is correct?"]]}, {"click": 1, "sents": [[7080, "The answer is B."], [9050, "Bucharest is an individual object, so the right relation is Part Of, and Part Of is transitive."], [16310, "Subset and membership are relations between objects and categories, and Romania is not being used as a category here."]]}]}, {"n": 20, "title": "Events", "dur": 35090, "clicks": [16505, 21190, 27425], "segs": [{"click": 0, "sents": [[360, "Section 10.3, events."], [3620, "Everything so far was static: what things are, what they are made of."], [8630, "But the world changes."], [10660, "Agents act, properties start and stop being true, and things happen at the same time."]]}, {"click": 1, "sents": [[16810, "First, why the approach from Chapter 7 is not enough."]]}, {"click": 2, "sents": [[21710, "Second, the event calculus, a logic built for reasoning about change."]]}, {"click": 3, "sents": [[27980, "Third, how to reason about time intervals, and about objects whose properties change over time."]]}]}, {"n": 21, "title": "Why We Need More Than Successor-State Axioms", "dur": 56240, "clicks": [14790, 27845, 36795], "segs": [{"click": 0, "sents": [[500, "In Chapter 7, the Wumpus agent used successor-state axioms."], [5500, "The world jumps from one state to the next, one action at a time, and every action is instantaneous."], [12780, "That works for simple puzzles."]]}, {"click": 1, "sents": [[15100, "But real actions take time."], [17750, "Filling a bathtub takes several minutes."], [20730, "How full is it halfway through?"], [23070, "The old model cannot talk about anything that happens during an action."]]}, {"click": 2, "sents": [[28370, "And real events overlap."], [30690, "You brush your teeth while the tub is filling."], [33650, "The old model assumes one action at a time."]]}, {"click": 3, "sents": [[37200, "The solution is the event calculus."], [40040, "Events become objects with a start time and an end time, time is continuous, and many events can overlap."], [48010, "Northgate needs exactly this: an I V infusion runs for an hour while vital signs are taken every fifteen minutes."]]}]}, {"n": 22, "title": "Event Calculus: The Core Predicates", "dur": 76140, "clicks": [15955, 24545, 34990, 45880, 56495, 64000], "segs": [{"click": 0, "sents": [[300, "The event calculus reasons about three kinds of objects: events, which are things that happen; fluents, which are facts that can change, like Maria has a fever; and time points."], [13470, "Six predicates do all the work."]]}, {"click": 1, "sents": [[16290, "T of f, t one, t two: fluent f is true at every moment between t one and t two."]]}, {"click": 2, "sents": [[25080, "Happens of e, t one, t two: event e starts at t one and ends at t two."], [32920, "Events have duration."]]}, {"click": 3, "sents": [[35540, "Initiates of e, f, t: event e makes fluent f become true at time t."], [43290, "This is how events switch facts on."]]}, {"click": 4, "sents": [[46260, "Terminates of e, f, t: event e makes fluent f stop being true at time t."], [53900, "This is how events switch facts off."]]}, {"click": 5, "sents": [[56850, "Initiated of f, t one, t two: f became true somewhere in that interval."]]}, {"click": 6, "sents": [[64350, "And Terminated: f stopped being true somewhere in that interval."], [70000, "Those last two are derived from the others."], [73040, "The first four are the ones you will use most."]]}]}, {"n": 23, "title": "Worked Example: Shankar's Flight", "dur": 77080, "clicks": [6790, 22470, 32275, 50170, 62315], "segs": [{"click": 0, "sents": [[380, "Let us model a real event: Shankar flies from San Francisco to Washington, D C."]]}, {"click": 1, "sents": [[7310, "First, we describe the event as an object."], [10670, "This is reification again."], [12720, "E one is a member of Flyings."], [15500, "The flyer of E one is Shankar."], [18130, "Its origin is San Francisco, and its destination is D C."]]}, {"click": 2, "sents": [[22810, "Second, when it happens: Happens of E one, t one, t two."], [28500, "The flight starts at t one and ends at t two."]]}, {"click": 3, "sents": [[32610, "Third, what it changes."], [35510, "E one terminates the fluent Shankar is at San Francisco, at time t one, when he takes off."], [42870, "And E one initiates the fluent Shankar is at D C, at time t two, when he lands."]]}, {"click": 4, "sents": [[50500, "Fourth, because E one is an object, we can keep adding facts: it was bumpy, and it lasted five hours."], [59480, "We never had to change any predicate."]]}, {"click": 5, "sents": [[62810, "That is why we reify."], [64970, "A single predicate, Fly of Shankar, San Francisco, D C, could never be given a duration or a bumpy label without inventing a new, bigger predicate every time."]]}]}, {"n": 24, "title": "Fluents on a Timeline: Inertia", "dur": 54370, "clicks": [5970, 14825, 19260, 25665, 32230], "segs": [{"click": 0, "sents": [[340, "Here is the same flight drawn on a timeline."], [3650, "Time runs left to right."]]}, {"click": 1, "sents": [[6490, "From time t zero, Shankar is in San Francisco."], [10730, "The fluent At Shankar comma S F is true."]]}, {"click": 2, "sents": [[15185, "From t one to t two, the flight event happens."]]}, {"click": 3, "sents": [[19775, "At t one, the flight terminates At S F."], [23775, "The blue bar stops."]]}, {"click": 4, "sents": [[26145, "At t two, the flight initiates At D C."], [30025, "A new green bar starts."]]}, {"click": 5, "sents": [[32705, "And the green bar keeps going."], [34795, "Why?"], [35655, "Because fluents persist until some event changes them."], [39685, "This is called inertia."], [41745, "No event has terminated At D C, so it is still true now."], [46465, "Inertia is what lets a hospital system assume Maria is still on Ward four, unless a transfer event says otherwise."]]}]}, {"n": 25, "title": "Time Intervals: Allen's Relations", "dur": 75190, "clicks": [14235, 21730, 30155, 37210, 51785, 60400], "segs": [{"click": 0, "sents": [[285, "Events take up intervals of time."], [3105, "James Allen defined a small vocabulary that describes how any two intervals relate."], [9395, "The blue bar is interval i, the gold bar is interval j."]]}, {"click": 1, "sents": [[14615, "Meet: i ends exactly when j begins."], [19025, "One monarch's reign meets the next."]]}, {"click": 2, "sents": [[22065, "Before: i ends, and there is a gap before j begins."], [26985, "World War One was before World War Two."]]}, {"click": 3, "sents": [[30525, "During: i lies completely inside j."], [34685, "A day is during a month."]]}, {"click": 4, "sents": [[37765, "Overlap: i starts first, and j starts before i ends."], [43365, "Elvis Presley's life, from 1935 to 1977, overlaps the 1950s without being contained in them."]]}, {"click": 5, "sents": [[52085, "Starts, Finishes, and Equals: the intervals share a start, share an end, or share both."]]}, {"click": 6, "sents": [[60765, "Add After, the reverse of Before, and any two intervals stand in exactly one of these relations."], [68455, "A hospital needs them constantly: did the rash appear during the antibiotic course, or before it started?"]]}]}, {"n": 26, "title": "Objects That Change: Time-Indexed Identity", "dur": 67800, "clicks": [17745, 26865, 41075, 53670], "segs": [{"click": 0, "sents": [[345, "A subtle problem."], [2105, "In first-order logic, a term names one object, forever."], [6805, "But President of U S A was George Washington in 1790 and Abraham Lincoln in 1861."], [14035, "How can one term name different people at different times?"]]}, {"click": 1, "sents": [[18085, "We cannot use logical equality."], [20775, "President of U S A equals George Washington would be true forever, which is wrong."]]}, {"click": 2, "sents": [[27285, "Instead we make equality a fluent."], [30495, "T of Equals of President of U S A and George Washington, from the beginning to the end of 1790."], [38275, "It is true only during that interval."]]}, {"click": 3, "sents": [[41365, "Remember: this Equals is a fluent that holds during an interval."], [46625, "It is not the logical equals sign, which can never change."], [50665, "This distinction is a favorite exam question."]]}, {"click": 4, "sents": [[54105, "At Northgate: the attending doctor of Maria equals Doctor Lee from Monday to Wednesday."], [61085, "Then Doctor Okafor takes over."], [63885, "Same term, different person, at different times."]]}]}, {"n": 27, "title": "Northgate Hospital: Maria's Night on a Timeline", "dur": 67220, "clicks": [4265, 18260, 24965, 32865, 39985, 48150], "segs": [{"click": 0, "sents": [[535, "Let us put Maria's night at Northgate on a timeline."]]}, {"click": 1, "sents": [[4835, "At one in the morning, event E one, her admission, initiates the fluent Maria is on Ward four."], [12275, "By inertia it stays true all the way to noon, because no transfer event terminates it."]]}, {"click": 2, "sents": [[18585, "At two in the morning, event E two, the onset of fever, initiates Fever of Maria."]]}, {"click": 3, "sents": [[25305, "At four, the antibiotic infusion, event E three, begins."], [30815, "It runs until seven."]]}, {"click": 4, "sents": [[33455, "At five, I V fluids, event E four, begin, and continue until ten."]]}, {"click": 5, "sents": [[40305, "At eight, event E five, the fever resolving, terminates the fever fluent."], [46365, "The red bar stops."]]}, {"click": 6, "sents": [[48635, "Now the system can reason."], [50925, "The antibiotic overlaps the I V fluids, so it checks that the drug and the fluid are compatible."], [57655, "And the antibiotic was given during the fever, which is exactly what a sepsis protocol requires."], [64035, "None of this is possible with the Chapter 7 model."]]}]}, {"n": 28, "title": "Check Your Understanding", "dur": 24240, "clicks": [10025], "segs": [{"click": 0, "sents": [[525, "Check your understanding."], [2385, "Shankar lands in D C at t two, and no later event mentions him."], [7815, "Why is he still in D C now?"]]}, {"click": 1, "sents": [[10335, "The answer is B, inertia."], [13395, "Initiates made the fluent true at t two, and nothing has terminated it since, so it persists."], [20685, "Fluents stay true until some event changes them."]]}]}, {"n": 29, "title": "Mental Objects and Modal Logic", "dur": 38420, "clicks": [15445, 23510, 29050], "segs": [{"click": 0, "sents": [[455, "Section 10.4, mental objects."], [4455, "Agents do not just act on the world; they know things, believe things, and want things."], [10945, "An agent that works with people must reason about what those people know."]]}, {"click": 1, "sents": [[15825, "First, why knowledge and belief break ordinary first-order logic, shown with the famous Superman problem."]]}, {"click": 2, "sents": [[24125, "Second, the fix: modal logic and possible worlds."]]}, {"click": 3, "sents": [[29595, "Third, the rules that define knowledge, and a subtle ambiguity in sentences like Bond knows that someone is a spy."]]}]}, {"n": 30, "title": "Propositional Attitudes", "dur": 54380, "clicks": [10620, 15315, 20220, 25510, 40765], "segs": [{"click": 0, "sents": [[335, "A propositional attitude is a relation between an agent and a proposition."], [5745, "The agent has some attitude, such as knowing, toward some statement."]]}, {"click": 1, "sents": [[11145, "Knows: Lois knows that Superman can fly."]]}, {"click": 2, "sents": [[15855, "Believes: the nurse believes Maria is febrile."]]}, {"click": 3, "sents": [[20765, "Wants: the pharmacist wants order seventeen to be safe."]]}, {"click": 4, "sents": [[25995, "Now, classical first-order logic has a property called referential transparency."], [32015, "If x equals y, then anything true of x is also true of y."], [37545, "You can always swap equals for equals."]]}, {"click": 5, "sents": [[41155, "That is perfect for arithmetic."], [43675, "Two plus two equals four, and four is less than five, so two plus two is less than five."], [51215, "But watch what happens when we apply it to knowledge."]]}]}, {"n": 31, "title": "The Superman Problem", "dur": 55720, "clicks": [11765, 22065, 28175, 44465], "segs": [{"click": 0, "sents": [[465, "Here is the most famous example in Chapter 10."], [3945, "Two facts."], [5215, "Superman and Clark Kent are the same person."], [8565, "And Lois Lane knows that Superman can fly."]]}, {"click": 1, "sents": [[12095, "Classical logic swaps equals for equals."], [16055, "Replace Superman with Clark, and we conclude: Lois knows that Clark can fly."]]}, {"click": 2, "sents": [[22545, "But that is false."], [24245, "Lois has no idea that mild-mannered Clark can fly."]]}, {"click": 3, "sents": [[28935, "Why?"], [29835, "Lois does not know that Clark is Superman."], [32935, "In a knowledge context, the description used to pick out the object matters, not just the object itself."], [39975, "Lois knows a fact about the man in the cape, not about the reporter."]]}, {"click": 4, "sents": [[44765, "This is called referential opacity."], [47835, "Inside knows and believes, you cannot freely substitute equal terms."], [53265, "So we need a different logic."]]}]}, {"n": 32, "title": "Modal Logic and Possible Worlds", "dur": 74560, "clicks": [20750, 41545, 56275], "segs": [{"click": 0, "sents": [[500, "Modal logic adds an operator, K sub A of P, meaning agent A knows P."], [8180, "Unlike a predicate, K takes a whole sentence as its argument."], [12730, "The meaning is given by possible worlds."], [15700, "On the left is w zero, the actual world, where Clark is Superman."]]}, {"click": 1, "sents": [[21120, "Lois does not know everything, so several worlds are consistent with what she knows."], [26680, "These are the worlds she considers possible."], [29460, "In all of them Superman flies, because she knows that."], [33190, "But in some, Clark is not Superman, because she does not know that he is."], [38290, "The arrows are called the accessibility relation."]]}, {"click": 2, "sents": [[41850, "The rule: agent A knows P in world w zero if and only if P is true in every world A considers possible."], [52130, "This one definition explains everything modal logic does."]]}, {"click": 3, "sents": [[56630, "Apply it."], [57830, "Can Superman fly?"], [59680, "True in every world Lois considers possible, so she knows it."], [64290, "Can Clark fly?"], [65920, "Not true in every one, because in some worlds Clark is just a reporter."], [70260, "So she does not know it."], [72080, "The Superman problem is solved."]]}]}, {"n": 33, "title": "The Rules of Knowledge (and a Warning)", "dur": 56550, "clicks": [3895, 18895, 31185, 36710], "segs": [{"click": 0, "sents": [[490, "Three rules define a rational knowing agent."]]}, {"click": 1, "sents": [[4250, "Closure: if agent a knows P, and knows that P implies Q, then a knows Q."], [12250, "Agents can draw conclusions from what they know."], [15400, "It is Modus Ponens inside the knowledge operator."]]}, {"click": 2, "sents": [[19400, "Truth: if a knows P, then P is true."], [23820, "You cannot know something false."], [26160, "This is what separates knowledge from belief; you can believe something false."]]}, {"click": 3, "sents": [[31510, "Introspection: if you know something, you know that you know it."]]}, {"click": 4, "sents": [[37275, "And a warning."], [38805, "Together, these rules imply that an agent knows every consequence of everything it knows."], [45065, "This is called logical omniscience, and it is unrealistic."], [49775, "Knowing the rules of arithmetic does not mean you know every theorem."], [53935, "It is a known limitation of this framework."]]}]}, {"n": 34, "title": "“Bond Knows That Someone Is a Spy” — Two Meanings", "dur": 71610, "clicks": [8780, 24060, 41350, 53005], "segs": [{"click": 0, "sents": [[325, "The English sentence Bond knows that someone is a spy is ambiguous."], [5935, "Modal logic separates the two meanings."]]}, {"click": 1, "sents": [[9115, "De re, Latin for about the thing: there exists a specific x such that Bond knows x is a spy."], [18145, "Bond knows who the spy is."], [20915, "The there-exists is outside the K."]]}, {"click": 2, "sents": [[24435, "De dicto, about the words: Bond knows that there exists a spy."], [30115, "He knows spies exist, but not who."], [33455, "In each world he considers possible, the spy could be a different person."], [38365, "The there-exists is inside the K."]]}, {"click": 3, "sents": [[41895, "The implication goes one way."], [44185, "If Bond knows who the spy is, then he certainly knows a spy exists."], [49495, "But knowing a spy exists does not tell him who."]]}, {"click": 4, "sents": [[53355, "A bonus."], [54815, "Modal logic also has temporal operators: G of Safe means the system is always safe; F of Done means it will eventually be done."], [65835, "Engineers use these to verify that chips and software can never reach an unsafe state."]]}]}, {"n": 35, "title": "Northgate Hospital: Who Knows What?", "dur": 61240, "clicks": [13325, 28015, 35265, 44485], "segs": [{"click": 0, "sents": [[305, "Northgate has its own Superman problem."], [3455, "Maria is the patient in bed twelve."], [6385, "The night nurse knows that the patient in bed twelve is febrile, but she has never seen Maria's name on a chart."]]}, {"click": 1, "sents": [[13885, "Does it follow that the nurse knows Maria is febrile?"], [17575, "No."], [18545, "That is referential opacity, exactly like Superman."], [22895, "She knows a fact under the description bed twelve, not under the name Maria."]]}, {"click": 2, "sents": [[28350, "Meanwhile the pharmacist knows Maria has a penicillin allergy, but does not know who is in bed twelve."]]}, {"click": 3, "sents": [[35600, "Here is the danger."], [37330, "The nurse is asked to give amoxicillin to bed twelve."], [41230, "No single person knows both facts at once."]]}, {"click": 4, "sents": [[44840, "A system that reasons about who knows what can catch this."], [49120, "It notices that the nurse does not know the allergy, and alerts her using the patient's name as well as the bed number."], [56510, "Modal logic is not just philosophy; it prevents real errors."]]}]}, {"n": 36, "title": "Check Your Understanding", "dur": 27410, "clicks": [6400], "segs": [{"click": 0, "sents": [[290, "Check your understanding."], [2320, "Which sentence says Bond knows who the spy is?"]]}, {"click": 1, "sents": [[7000, "The answer is B."], [8810, "The there-exists is outside the K, so there is one specific person that Bond knows is a spy."], [16240, "That is the de re reading."], [18430, "Option A is de dicto: Bond only knows that spies exist."], [23570, "Option C is a tautology that Bond knows trivially."]]}]}, {"n": 37, "title": "Reasoning Systems for Categories", "dur": 36950, "clicks": [13950, 22225, 29830], "segs": [{"click": 0, "sents": [[330, "Section 10.5."], [2590, "We now have a vocabulary for categories."], [5700, "This section asks: what systems reason about categories quickly?"], [11070, "Two answers have shaped modern AI."]]}, {"click": 1, "sents": [[14490, "First, semantic networks, which draw knowledge as a graph."], [19400, "They grew into today's knowledge graphs."]]}, {"click": 2, "sents": [[22870, "Second, how inheritance works in a graph, and what happens when two inherited facts conflict."]]}, {"click": 3, "sents": [[30175, "Third, description logics, the formal foundation of the Web Ontology Language, OWL."]]}]}, {"n": 38, "title": "Semantic Networks: Knowledge as a Graph", "dur": 72730, "clicks": [11625, 20315, 29650, 39705, 47970], "segs": [{"click": 0, "sents": [[635, "A semantic network draws knowledge as a graph."], [4075, "Nodes are objects or categories; labeled arrows are relations."], [9135, "We start with the category Persons."]]}, {"click": 1, "sents": [[11925, "Female persons and male persons are both subsets of persons."], [17025, "The blue arrows are labeled Subset Of."]]}, {"click": 2, "sents": [[20815, "Mary is a member of female persons; John is a member of male persons."], [26605, "The gold arrows are labeled Member Of."]]}, {"click": 3, "sents": [[28865, "Arrows can carry any binary relation."], [33025, "Here, John's node links to Mary with Sister Of, meaning Mary is John's sister."]]}, {"click": 4, "sents": [[40085, "And a property attached to a category, Legs equals two on Persons, acts as a default for every member."]]}, {"click": 5, "sents": [[48335, "Every link is just a logical statement drawn as an arrow."], [52565, "Subset Of means female persons is a subset of persons; Member Of means Mary belongs to female persons."], [62195, "So a semantic network is not a rival to logic."], [66125, "It is a restricted, drawn form of logic, which makes inheritance easy to compute and easy to see."]]}]}, {"n": 39, "title": "Inheritance in a Network: Specific Beats General", "dur": 48480, "clicks": [9045, 13740, 19125, 28510], "segs": [{"click": 0, "sents": [[295, "How many legs does each person have?"], [2925, "The inheritance algorithm starts at the individual and climbs upward until it finds an answer."]]}, {"click": 1, "sents": [[9375, "Start at Mary."], [11045, "Her node has no value for Legs."]]}, {"click": 2, "sents": [[14265, "Climb the Member Of link to female persons."], [17585, "Still no value."]]}, {"click": 3, "sents": [[19605, "Climb the Subset Of link to persons."], [22655, "Legs equals two."], [24515, "So Mary has two legs, an inherited default."]]}, {"click": 4, "sents": [[28975, "Now John."], [30335, "His own node says Legs equals one."], [33585, "The algorithm finds it immediately and stops; it never climbs further."], [38695, "John's local value overrides the default."], [41835, "The rule is: specific beats general."], [45005, "Section 10.6 will make this idea formal."]]}]}, {"n": 40, "title": "Multiple Inheritance: The Nixon Diamond", "dur": 51900, "clicks": [9040, 15120, 21605, 29610], "segs": [{"click": 0, "sents": [[495, "An object can belong to more than one category, and the inherited facts can conflict."], [6265, "The classic example is the Nixon diamond."]]}, {"click": 1, "sents": [[9335, "Richard Nixon was a Republican and a Quaker."], [12745, "He is a member of both categories."]]}, {"click": 2, "sents": [[15545, "By default, Republicans are not pacifists, and Quakers are pacifists."]]}, {"click": 3, "sents": [[22145, "Was Nixon a pacifist?"], [24345, "Two equally good inheritance paths give opposite answers."], [28465, "Conflict."]]}, {"click": 4, "sents": [[30050, "What can a system do?"], [31990, "Prefer the more specific category, but neither is more specific here."], [36740, "Use the formal methods of Section 10.6."], [39950, "Or ban multiple inheritance, as Java does, which is too restrictive for real knowledge."], [46180, "The careful answer is to stay agnostic and report both possibilities, rather than guess."]]}]}, {"n": 41, "title": "Limitation: Links Are Binary — So Reify", "dur": 49680, "clicks": [15085, 23885, 28735, 31080, 33960, 36810], "segs": [{"click": 0, "sents": [[390, "Semantic networks have one built-in limitation: every arrow connects exactly two nodes."], [7560, "But some facts have more than two participants."], [10810, "Shankar flew from New York to New Delhi yesterday has four."]]}, {"click": 1, "sents": [[15620, "The fix is reification."], [17950, "Make the flight itself a node: Fly seventeen, a member of Fly Events."]]}, {"click": 2, "sents": [[24380, "Then link it with binary arrows."], [27020, "Agent: Shankar."]]}, {"click": 3, "sents": [[29090, "Origin: New York."]]}, {"click": 4, "sents": [[31410, "Destination: New Delhi."]]}, {"click": 5, "sents": [[34590, "During: yesterday."]]}, {"click": 6, "sents": [[37380, "It is exactly the same trick we used in the event calculus."], [41430, "Every multi-argument fact becomes an event node plus binary links."], [46350, "Knowledge graphs today store almost everything this way."]]}]}, {"n": 42, "title": "Description Logics: Formal, Fast Category Reasoning", "dur": 75520, "clicks": [14920, 24240, 32530, 43920, 61490], "segs": [{"click": 0, "sents": [[315, "Description logics grew out of semantic networks to make category reasoning formal and fast."], [6915, "The design goal: answer category questions in polynomial time, something full first-order logic cannot promise."]]}, {"click": 1, "sents": [[15385, "Three tasks."], [16925, "Subsumption: is one category a subset of another?"], [21025, "For example, is every bachelor an adult?"]]}, {"click": 2, "sents": [[24495, "Classification: which categories does a given object belong to?"], [29815, "Is Maria a high-risk patient?"]]}, {"click": 3, "sents": [[33125, "Consistency: can a category have any members at all?"], [37585, "Can a patient be both an inpatient and discharged?"], [41225, "If not, a definition is broken."]]}, {"click": 4, "sents": [[44355, "The CLASSIC language builds category definitions from a few operators."], [49095, "And combines categories."], [51245, "All says every filler of a role is in a category."], [55205, "At Least and At Most count role fillers."], [58805, "Fills names a specific filler."]]}, {"click": 5, "sents": [[61995, "The trade-off: description logics are fast because they restrict negation and disjunction, which would force expensive case-by-case analysis."], [71695, "You give up some expressive power to gain guaranteed speed."]]}]}, {"n": 43, "title": "Worked Example: CLASSIC vs FOL", "dur": 63450, "clicks": [17225, 31010, 33735, 39665, 45380, 50445], "segs": [{"click": 0, "sents": [[325, "Compare the two notations."], [2385, "In first-order logic, a bachelor is defined with an if-and-only-if."], [7475, "In CLASSIC, we simply write: Bachelor equals And of Unmarried, Adult, Male."], [13825, "Same meaning, but algebraic and composable."]]}, {"click": 1, "sents": [[17545, "Now a complicated category: men with at least three sons, all unemployed and married to doctors, and at most two daughters, all professors of physics or math."], [29585, "Watch it build."]]}, {"click": 2, "sents": [[31465, "Start with And of Man."]]}, {"click": 3, "sents": [[34265, "Add the counts: at least three sons and at most two daughters."]]}, {"click": 4, "sents": [[40215, "All sons are unemployed, married, and every spouse is a doctor."]]}, {"click": 5, "sents": [[45845, "All daughters are professors whose department is physics or math."]]}, {"click": 6, "sents": [[50955, "Subsumption is now easy."], [53415, "Is every bachelor an adult?"], [55925, "Adult is one of the conjuncts in the definition, so yes, and the system can check that in polynomial time."]]}]}, {"n": 44, "title": "Northgate Hospital: Automatic Classification", "dur": 66550, "clicks": [20460, 26420, 32630, 41410, 53970], "segs": [{"click": 0, "sents": [[475, "At Northgate, categories can be defined with description-logic operators."], [5605, "Sepsis Watch: a patient whose status includes febrile and tachycardic, which means a fast heart rate."], [13165, "Penicillin Risk: a patient whose prescriptions are all beta-lactams and whose allergies include penicillin."]]}, {"click": 1, "sents": [[20855, "When new data arrives about Maria, the reasoner classifies her automatically."]]}, {"click": 2, "sents": [[26905, "Her status is febrile and tachycardic, so she is placed in Sepsis Watch."]]}, {"click": 3, "sents": [[33120, "She is prescribed amoxicillin, a beta-lactam, and is allergic to penicillin, so she is placed in Penicillin Risk."]]}, {"click": 4, "sents": [[41800, "Subsumption and consistency checks also catch design errors before deployment: every Penicillin Risk member must be a patient, and the definition must be satisfiable."]]}, {"click": 5, "sents": [[54370, "This is not hypothetical."], [56590, "SNOMED C T, a clinical terminology used in hospitals worldwide with hundreds of thousands of concepts, is built on a description logic."]]}]}, {"n": 45, "title": "Check Your Understanding", "dur": 27950, "clicks": [10335], "segs": [{"click": 0, "sents": [[530, "Check your understanding."], [2430, "John's node says Legs equals one, and Persons says Legs equals two."], [8140, "What does inheritance give John?"]]}, {"click": 1, "sents": [[10690, "The answer is B, one."], [13360, "The search starts at John's own node and stops at the first value it finds."], [19000, "Specific beats general."], [21370, "A conflict only arises when two parents at the same level disagree, as in the Nixon diamond."]]}]}, {"n": 46, "title": "Reasoning with Default Information", "dur": 38520, "clicks": [17440, 24535, 31265], "segs": [{"click": 0, "sents": [[520, "Section 10.6, the last section, and perhaps the most important in practice."], [7070, "Almost nothing we have written is universally true."], [10650, "Birds fly, except penguins."], [13250, "Patients tolerate amoxicillin, except the allergic ones."]]}, {"click": 1, "sents": [[17810, "First, why classical logic cannot withdraw a conclusion, and why people constantly do."]]}, {"click": 2, "sents": [[25060, "Second, two formal methods for defaults: circumscription and default logic."]]}, {"click": 3, "sents": [[31595, "Third, truth maintenance systems, which retract beliefs efficiently when the facts change."]]}]}, {"n": 47, "title": "Monotonic vs Nonmonotonic Reasoning", "dur": 50070, "clicks": [15485, 27630, 32240, 38490], "segs": [{"click": 0, "sents": [[475, "Classical logic is monotonic: if the knowledge base entails alpha, then adding any new fact beta still entails alpha."], [10115, "Adding facts can never remove a conclusion."], [13335, "That is right for mathematics."]]}, {"click": 1, "sents": [[15925, "Common-sense reasoning is nonmonotonic."], [19065, "Something can follow from what we know, and then stop following once new evidence arrives."], [24975, "Our beliefs can grow and shrink."]]}, {"click": 2, "sents": [[28095, "You see a parked car."], [29885, "You assume it has four wheels."]]}, {"click": 3, "sents": [[32735, "Then you see it jacked up, with the owner holding a wheel."], [36535, "You retract your assumption."]]}, {"click": 4, "sents": [[39045, "Retracting is not a flaw in human reasoning."], [42365, "It is the rational response to incomplete information."], [46145, "The challenge for AI is to do it in a principled way."]]}]}, {"n": 48, "title": "Circumscription: Assume Things Are Normal", "dur": 70360, "clicks": [17550, 26285, 35415, 50255, 57695], "segs": [{"click": 0, "sents": [[555, "John McCarthy's circumscription, from 1980, says: assume things are as normal as possible."], [7785, "We add an Abnormal condition to each default rule."], [11555, "Here: if x is a bird and x is not abnormal, then x flies."]]}, {"click": 1, "sents": [[17875, "To circumscribe Abnormal one means: assume it is false for everything, unless something forces it to be true."]]}, {"click": 2, "sents": [[26820, "We know Tweety is a bird."], [28940, "Nothing says Tweety is abnormal, so we assume it is not, and conclude Tweety flies."]]}, {"click": 3, "sents": [[35730, "Later we learn Tweety is a penguin, and penguins are abnormal birds."], [41300, "Now Abnormal one of Tweety is forced true, the rule no longer applies, and the conclusion that Tweety flies is withdrawn."]]}, {"click": 4, "sents": [[50800, "Formally, among all models of the knowledge base, we prefer the ones with the fewest abnormal objects."]]}, {"click": 5, "sents": [[58050, "Compare this with Prolog's closed-world assumption, which makes every unknown atom false."], [64450, "Circumscription is more surgical: it minimizes only the predicates you name."]]}]}, {"n": 49, "title": "The Nixon Diamond, Formally", "dur": 52170, "clicks": [14480, 23420, 32750], "segs": [{"click": 0, "sents": [[530, "Here is the Nixon diamond in circumscription."], [3730, "Nixon is a Republican and a Quaker."], [6920, "Each default rule gets its own Abnormal predicate: Ab two for Republicans, Ab three for Quakers."]]}, {"click": 1, "sents": [[14770, "Model one: make Nixon abnormal as a Republican."], [19310, "The Quaker default fires, and Nixon is a pacifist."]]}, {"click": 2, "sents": [[23970, "Model two: make Nixon abnormal as a Quaker."], [28220, "The Republican default fires, and Nixon is not a pacifist."]]}, {"click": 3, "sents": [[33020, "Each model has exactly one abnormality, so they are equally preferred, and circumscription stays agnostic."], [41290, "That is the honest answer: the facts do not settle the question."], [46070, "If you decide that one rule outranks the other, prioritized circumscription can break the tie."]]}]}, {"n": 50, "title": "Default Logic (Reiter, 1980)", "dur": 65069, "clicks": [20140, 35300, 41995, 52750], "segs": [{"click": 0, "sents": [[280, "Raymond Reiter's default logic, also from 1980, takes a different route: special default rules."], [8460, "Read P colon J slash C as: if the prerequisite P holds, and each justification J is consistent with what we know, then conclude C."]]}, {"click": 1, "sents": [[20480, "Birds fly becomes: Bird of x, colon, Flies of x, slash, Flies of x."], [28550, "If x is a bird, and it is consistent to believe x flies, conclude x flies."]]}, {"click": 2, "sents": [[35740, "The Nixon diamond becomes two default rules, one for Republicans and one for Quakers."]]}, {"click": 3, "sents": [[42350, "Default logic produces two extensions."], [45640, "One contains Nixon is a pacifist; the other contains Nixon is not a pacifist."]]}, {"click": 4, "sents": [[53330, "An extension is a maximal consistent set of conclusions."], [57520, "When there are several, the system is genuinely ambiguous, and default logic says so, just as circumscription did."]]}]}, {"n": 51, "title": "Truth Maintenance Systems (TMS)", "dur": 70750, "clicks": [15875, 35630, 57730], "segs": [{"click": 0, "sents": [[320, "Nonmonotonic reasoning raises a practical problem."], [4180, "When a belief is retracted, what else must go with it?"], [8270, "Re-deriving the entire knowledge base from scratch is far too slow."], [13150, "Truth maintenance systems solve this."]]}, {"click": 1, "sents": [[16070, "A justification-based truth maintenance system, or J T M S, records why each belief is held, its justifications."], [25610, "When a premise P is retracted, it removes every belief whose only support depended on P."], [32530, "Beliefs that have another support survive."]]}, {"click": 2, "sents": [[36100, "An assumption-based system, or A T M S, keeps many hypothetical worlds at once."], [42970, "Each belief is labeled with the sets of assumptions under which it holds."], [47670, "That is ideal for diagnosis: a car that will not start could be a dead battery or no fuel, and the A T M S tracks both explanations together."]]}, {"click": 3, "sents": [[58120, "The cost: truth maintenance is at least as hard as propositional inference."], [63510, "But it does targeted repair on the belief graph instead of rebuilding everything, which is what real-time systems need."]]}]}, {"n": 52, "title": "Worked Example: JTMS Retraction", "dur": 63110, "clicks": [16465, 18990, 26805, 33890, 51145], "segs": [{"click": 0, "sents": [[310, "Let us watch a J T M S retract a belief."], [3850, "The knowledge base has P and the rule P implies Q, so Q is believed."], [10010, "The JTMS records Q's justification: the set P and P implies Q."]]}, {"click": 1, "sents": [[16940, "Now P is retracted."]]}, {"click": 2, "sents": [[19330, "Case A: if that was Q's only justification, Q loses its support and is removed as well."]]}, {"click": 3, "sents": [[27120, "But what if the knowledge base also contains other support for Q?"], [31760, "Let us rewind and add some."]]}, {"click": 4, "sents": [[34350, "Case B: the knowledge base also has R and the rule R implies Q."], [40300, "That gives Q a second justification."], [43240, "When P is retracted, justification one fails, but justification two still holds."], [49710, "Q survives."]]}, {"click": 5, "sents": [[51450, "In both cases the JTMS looked only at the beliefs that depended on P."], [57580, "It never re-derived the whole knowledge base."], [60770, "That is what makes it efficient."]]}]}, {"n": 53, "title": "Northgate Hospital: Defaults and a Corrected Chart", "dur": 61420, "clicks": [10705, 21650, 33020, 45525], "segs": [{"click": 0, "sents": [[480, "Now Northgate."], [2010, "The default: patients tolerate amoxicillin unless they are abnormal."], [7140, "And a penicillin allergy makes a patient abnormal."]]}, {"click": 1, "sents": [[11100, "At eight in the morning the chart records Maria's penicillin allergy."], [15540, "She is abnormal, so the default is blocked, and the system raises an alert on amoxicillin."]]}, {"click": 2, "sents": [[22020, "At ten thirty, an allergist reviews the record: the allergy was a documentation error, and Maria tolerated amoxicillin last year."], [30890, "The allergy fact is retracted."]]}, {"click": 3, "sents": [[33360, "The truth maintenance system removes every belief that depended only on the allergy."], [39260, "The alert is withdrawn, and the default comes back: Maria tolerates amoxicillin."]]}, {"click": 4, "sents": [[46020, "But Maria's sepsis risk has its own support: her fever and heart rate."], [51130, "It stays exactly where it was."], [53600, "That is nonmonotonic reasoning and truth maintenance working together, which is exactly what a real clinical system needs."]]}]}, {"n": 54, "title": "Check Your Understanding", "dur": 25380, "clicks": [10515], "segs": [{"click": 0, "sents": [[290, "Check your understanding."], [2140, "A system believes Tweety flies, learns Tweety is a penguin, and withdraws the belief."], [8600, "What kind of reasoning is this?"]]}, {"click": 1, "sents": [[10870, "The answer is B, nonmonotonic."], [14270, "New information removed a conclusion, which classical, monotonic logic can never do."], [20510, "It is not unsound; it is the rational response to new evidence."]]}]}, {"n": 55, "title": "Common Misconceptions to Avoid", "dur": 60100, "clicks": [4405, 12460, 20855, 30060, 40285, 51005], "segs": [{"click": 0, "sents": [[530, "Six misconceptions that show up again and again."]]}, {"click": 1, "sents": [[4900, "Part Of is not Subset Of."], [8180, "Bucharest is part of Romania, but it is not a subset."]]}, {"click": 2, "sents": [[12760, "A category is not a pile."], [15460, "The category Apples has no weight; a Bunch Of particular apples does."]]}, {"click": 3, "sents": [[21270, "Time-indexed equality is not the equals sign."], [25050, "T of Equals is a fluent; logical identity never changes."]]}, {"click": 4, "sents": [[30370, "Knowing P or not P is a tautology, but it does not mean you know P or you know not P."], [37720, "An agent can simply be ignorant."]]}, {"click": 5, "sents": [[40630, "Circumscription is not the closed-world assumption."], [44370, "The closed-world assumption minimizes everything; circumscription only the predicates you name."]]}, {"click": 6, "sents": [[51530, "And an extension is not the answer."], [54430, "Several extensions means genuine ambiguity, and the system should report all of them."]]}]}, {"n": 56, "title": "How Chapter 10 Fits Together", "dur": 52260, "clicks": [5570, 12755, 23245, 32080, 40310], "segs": [{"click": 0, "sents": [[360, "Here is how the six sections fit together, built like a house from the ground up."]]}, {"click": 1, "sents": [[6040, "The foundation is the upper ontology from Section 10.1: what kinds of things exist."]]}, {"click": 2, "sents": [[13260, "The walls are objects and events, from Sections 10.2 and 10.3: things, parts, and measures, plus actions and time."]]}, {"click": 3, "sents": [[23630, "The upper floor is mental objects, from Section 10.4: what agents know and believe about everything below."]]}, {"click": 4, "sents": [[32440, "The plumbing is the reasoning systems of Section 10.5, which make inheritance and classification fast."]]}, {"click": 5, "sents": [[40880, "And the weatherproofing is default reasoning, Section 10.6."], [45450, "Without it, the house only works in perfect conditions, because almost every real rule has exceptions."]]}]}, {"n": 57, "title": "Where These Ideas Run Today", "dur": 56780, "clicks": [5820, 13840, 24540, 33200, 42400, 47950], "segs": [{"click": 0, "sents": [[320, "These ideas are not academic."], [2880, "They run in systems you use every day."]]}, {"click": 1, "sents": [[6360, "Knowledge graphs at Google and Wikidata use ontology categories, inheritance, and reified facts."]]}, {"click": 2, "sents": [[14280, "Clinical systems use SNOMED C T, a description logic, along with symptom timelines and default dosing rules, much like our Northgate examples."]]}, {"click": 3, "sents": [[24840, "Autonomous vehicles use an ontology of roads, vehicles, and pedestrians, and reason about events in continuous time."]]}, {"click": 4, "sents": [[34050, "Legal and compliance systems classify contracts, treat presumptions as defaults, and revise beliefs as evidence arrives."]]}, {"click": 5, "sents": [[42710, "NASA's spacecraft planners reason about activities that overlap in time."]]}, {"click": 6, "sents": [[48750, "And engineers verify chips and software with temporal modal logic, proving that a system is always safe."]]}]}, {"n": 58, "title": "Chapter 10 Summary", "dur": 66340, "clicks": [4155, 13085, 25105, 39010, 49995, 57850], "segs": [{"click": 0, "sents": [[550, "Let us summarize Chapter 10 in six ideas."]]}, {"click": 1, "sents": [[4680, "One: general-purpose upper ontologies give every domain a shared frame, and inheritance flows down it."]]}, {"click": 2, "sents": [[13670, "Two: categories and objects."], [16660, "Membership, subsets, partitions, Part Of, measures, things versus stuff, and typical members."]]}, {"click": 3, "sents": [[25440, "Three: the event calculus."], [28130, "Events are objects; fluents are switched on and off by Initiates and Terminates; inertia keeps them on; and Allen's relations compare intervals."]]}, {"click": 4, "sents": [[39240, "Four: modal logic."], [41850, "Knowledge is referentially opaque, and an agent knows P when P holds in every world it considers possible."]]}, {"click": 5, "sents": [[50540, "Five: semantic networks make inheritance fast, and description logics make classification tractable."]]}, {"click": 6, "sents": [[58105, "Six: real knowledge has exceptions, handled by circumscription, default logic, and truth maintenance."]]}]}, {"n": 59, "title": "The Whole Picture", "dur": 41500, "clicks": [2800, 11045, 20540], "segs": [{"click": 0, "sents": [[565, "Let us close the whole session."]]}, {"click": 1, "sents": [[3305, "Chapter 9 taught us how to reason: unification, forward and backward chaining, and resolution."]]}, {"click": 2, "sents": [[11565, "Chapter 10 taught us what to reason about: ontologies, events and time, what agents know, and how to handle exceptions."]]}, {"click": 3, "sents": [[20805, "Together they make a knowledge-based agent."], [24335, "Maria's alert fired because good knowledge met a good inference engine, and it was withdrawn, correctly, when the knowledge changed."], [34035, "Thank you for your attention."], [35895, "Review the check-your-understanding questions, and post any questions to the discussion board."]]}]}]};
